                                cur['bg'] = ('256', codes[k+2]); k += 2
                            elif k+1 < len(codes) and codes[k+1] == 2:
                                cur['bg'] = ('rgb', codes[k+2], codes[k+3], codes[k+4]); k += 4
                        elif code == 49: cur['bg'] = None
                        elif 90 <= code <= 97: cur['fg'] = code-90+8
                        elif 100 <= code <= 107: cur['bg'] = code-100+8
                        k += 1
                continue
