use serde::{Serialize, Deserialize};
use serde_json::Value;

#[derive(Debug, Serialize, Deserialize)]
pub enum Message {
    Refresh,
    LogInfo(String),
    FocusByIndex(usize),
    Call { command: String, args: Option<Vec<String>> },
}

fn yaml_to_json(y: &str) -> String {
    // emulate: parse yaml -> value -> to_string
    y.to_string()
}

fn t(y: &str) {
    println!("--- {:?}", y);
    match serde_json::from_str::<Message>(y) {
        Ok(v) => println!("OK {:?}", v),
