//! A pragmatic YAML 1.2 (core schema) parser producing an ordered tree of nodes,
//! modelled after libyaml's scanner/parser error reporting.

use std::fmt;

#[derive(Debug, Clone, PartialEq)]
pub enum ScalarStyle {
    Plain,
    SingleQuoted,
    DoubleQuoted,
    Literal,
    Folded,
}

#[derive(Debug, Clone, PartialEq)]
pub enum Resolved {
    Null,
    Bool(bool),
    Int(i64),
    Float(f64),
    Str,
}

#[derive(Debug, Clone, PartialEq)]
pub enum Node {
    Scalar {
        raw: String,
        resolved: Resolved,
        style: ScalarStyle,
    },
    Seq(Vec<Node>),
    Map(Vec<(String, Node)>),
}

impl Node {
    pub fn is_null(&self) -> bool {
        matches!(self, Node::Scalar { resolved: Resolved::Null, .. })
    }
}

#[derive(Debug, Clone)]
pub struct Error {
    pub message: String,
}

impl Error {
    fn new(message: String) -> Self {
        Error { message }
    }
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.message)
    }
}

pub type Result<T> = std::result::Result<T, Error>;

const SINGLE_QUOTE: char = '\'';
const DOUBLE_QUOTE: char = '"';

struct Scanner {
    chars: Vec<char>,
    idx: usize,
}

#[derive(Debug, Clone, Copy, PartialEq)]
enum Mark {
    At(usize), // absolute char index
}

impl Scanner {
    fn line_col(&self, idx: usize) -> (usize, usize) {
        let mut line = 0;
        let mut col = 0;
        for c in self.chars.iter().take(idx) {
            if *c == '\n' {
                line += 1;
                col = 0;
            } else {
                col += 1;
            }
        }
        (line, col)
    }
}

pub struct Parser {
    s: Scanner,
    anchors: Vec<(String, Node)>,
}

fn is_space(c: char) -> bool {
    c == ' ' || c == '\t'
}

fn is_break(c: char) -> bool {
    c == '\n' || c == '\r'
}

fn is_blank(c: char) -> bool {
    is_space(c) || is_break(c)
}

/// A resolved-position helper: (index, line, column) with 0-based line/column.
#[derive(Debug, Clone, Copy)]
struct Pos {
    idx: usize,
    line: usize,
    col: usize,
}

impl Parser {
    pub fn new(input: &str) -> Parser {
        Parser {
            s: Scanner {
                chars: input.chars().collect(),
                idx: 0,
            },
            anchors: Vec::new(),
        }
    }

    fn pos(&self, idx: usize) -> Pos {
        let (line, col) = self.s.line_col(idx);
        Pos { idx, line, col }
    }

    fn cur(&self) -> Option<char> {
        self.s.chars.get(self.s.idx).copied()
    }

    fn peek(&self, n: usize) -> Option<char> {
        self.s.chars.get(self.s.idx + n).copied()
    }

    fn at_end(&self) -> bool {
        self.s.idx >= self.s.chars.len()
    }

    fn bump(&mut self) -> Option<char> {
        let c = self.cur();
        if c.is_some() {
            self.s.idx += 1;
        }
        c
    }

    fn err<T>(&self, pos: Pos, problem: &str, context: Option<(&str, Pos)>) -> Result<T> {
        let (l, c) = (pos.line + 1, pos.col + 1);
        let mut msg = format!("{} at line {} column {}", problem, l, c);
        if let Some((ctx, cpos)) = context {
            msg += &format!(", {} at line {} column {}", ctx, cpos.line + 1, cpos.col + 1);
        }
        Err(Error::new(msg))
    }

    /// Skip whitespace, comments and line breaks. Returns false at EOF.
    fn skip_ws_and_comments(&mut self) -> bool {
        loop {
            match self.cur() {
                Some(c) if is_blank(c) => {
                    self.bump();
                }
                Some('#') => {
                    while let Some(c) = self.cur() {
                        if is_break(c) {
                            break;
                        }
                        self.bump();
                    }
                }
                _ => return !self.at_end(),
            }
        }
    }
}

impl Parser {
    /// Parse a whole stream. Returns the document node (null if empty).
    pub fn parse(&mut self) -> Result<Node> {
        // skip directives / document markers
        let mut doc_start: Option<Pos> = None;
        let mut saw_doc_end = false;
        let mut docs: usize = 0;
        let mut result: Option<Node> = None;
        loop {
            self.skip_ws_and_comments();
            if self.at_end() {
                break;
            }
            // directive line
            if self.cur() == Some('%') {
                let start = self.s.idx;
                while let Some(c) = self.cur() {
                    if is_break(c) {
                        break;
                    }
                    self.bump();
                }
                let _ = start;
                continue;
            }
            if self.starts_with("---") {
                let spos = self.pos(self.s.idx);
                self.bump();
                self.bump();
                self.bump();
                docs += 1;
                if docs > 1 {
                    return Err(Error::new(
                        "deserializing from YAML containing more than one document is not supported"
                            .to_string(),
                    ));
                }
                doc_start = Some(spos);
                continue;
            }
            if self.starts_with("...") {
                for _ in 0..3 {
                    self.bump();
                }
                saw_doc_end = true;
                continue;
            }
            let node = self.parse_node(None, true)?;
            result = Some(node);
            docs += 1;
            if docs > 1 {
                return Err(Error::new(
                    "deserializing from YAML containing more than one document is not supported"
                        .to_string(),
                ));
            }
        }
        if saw_doc_end && result.is_none() {
            return Ok(Node::Scalar {
                raw: String::new(),
                resolved: Resolved::Null,
                style: ScalarStyle::Plain,
            });
        }
        Ok(result.unwrap_or(Node::Scalar {
            raw: String::new(),
            resolved: Resolved::Null,
            style: ScalarStyle::Plain,
        }))
    }

    fn starts_with(&self, pat: &str) -> bool {
        let p: Vec<char> = pat.chars().collect();
        for (i, c) in p.iter().enumerate() {
            match self.peek(i) {
                Some(x) if x == *c => {}
                _ => return false,
            }
        }
        true
    }

    /// Parse a node in the given context. `block_allowed` tells whether block
    /// collections may start here.
    fn parse_node(&mut self, indent: Option<usize>, block_allowed: bool) -> Result<Node> {
        self.skip_ws_and_comments();
        if self.at_end() {
            return Ok(Node::Scalar {
                raw: String::new(),
                resolved: Resolved::Null,
                style: ScalarStyle::Plain,
            });
        }
        let start = self.pos(self.s.idx);
        // anchor / tag prefixes
        let mut anchor: Option<String> = None;
        let mut tag: Option<String> = None;
        loop {
            match self.cur() {
                Some('&') => {
                    self.bump();
                    let name = self.read_while(|c| !is_blank(c) && c != ',' && c != ']' && c != '}');
                    anchor = Some(name);
                    self.skip_ws_and_comments();
                }
                Some('!') => {
                    let t = self.read_tag();
                    tag = Some(t);
                    self.skip_ws_and_comments();
                }
                _ => break,
            }
        }
        let node = match self.cur() {
            Some('*') => {
                self.bump();
                let name = self.read_while(|c| !is_blank(c) && c != ',' && c != ']' && c != '}');
                match self.anchors.iter().find(|(a, _)| a == &name) {
                    Some((_, n)) => n.clone(),
                    None => {
                        return self.err(
                            start,
                            &format!("found undefined alias {}", name),
                            None,
                        )
                    }
                }
            }
            Some('[') => self.parse_flow_seq()?,
            Some('{') => self.parse_flow_map()?,
            Some('|') | Some('>') if block_allowed => self.parse_block_scalar(indent)?,
            Some('-') if block_allowed && self.is_block_seq_entry() => self.parse_block_seq(indent)?,
            _ => {
                if block_allowed && self.is_block_map_entry() {
                    self.parse_block_map(indent)?
                } else {
                    self.parse_scalar(indent)?
                }
            }
        };
        if let Some(name) = anchor {
            self.anchors.push((name, node.clone()));
        }
        let node = if let Some(t) = tag {
            apply_tag(t, node)
        } else {
            node
        };
        Ok(node)
    }

    fn read_while<F: Fn(char) -> bool>(&mut self, f: F) -> String {
        let mut out = String::new();
        while let Some(c) = self.cur() {
            if f(c) {
                out.push(c);
                self.bump();
            } else {
                break;
            }
        }
        out
    }

    fn read_tag(&mut self) -> String {
        // handle !!str, !foo, !<tag>
        if self.cur() == Some('!') {
            self.bump();
        }
        if self.cur() == Some('<') {
            self.bump();
            let mut out = String::from("!");
            out.push_str(&self.read_while(|c| c != '>'));
            if self.cur() == Some('>') {
                self.bump();
            }
            return out;
        }
        let mut out = String::from("!");
        out.push_str(&self.read_while(|c| !is_blank(c) && c != ',' && c != ']' && c != '}'));
        out
    }

    fn is_block_seq_entry(&self) -> bool {
        // '-' followed by space/eol
        if self.cur() != Some('-') {
            return false;
        }
        match self.peek(1) {
            None => true,
            Some(c) => is_blank(c),
        }
    }

    fn is_block_map_entry(&self) -> bool {
        // Look ahead on the current line for a ':' followed by space or eol,
        // outside of quotes/flow.
        let mut i = self.s.idx;
        let mut depth = 0i32;
        let mut quote: Option<char> = None;
        while i < self.s.chars.len() {
            let c = self.s.chars[i];
            if let Some(q) = quote {
                if c == q {
                    if q == SINGLE_QUOTE && self.s.chars.get(i + 1) == Some(&SINGLE_QUOTE) {
                        i += 2;
                        continue;
                    }
                    quote = None;
                }
                i += 1;
                continue;
            }
            match c {
                '"' | '\'' => quote = Some(c),
                '[' | '{' => depth += 1,
                ']' | '}' => depth -= 1,
                '#' if depth == 0 && i > self.s.idx && is_space(self.s.chars[i - 1]) => return false,
                ':' if depth == 0 => {
                    return match self.s.chars.get(i + 1) {
                        None => true,
                        Some(n) => is_blank(*n),
                    }
                }
                '\n' | '\r' => return false,
                _ => {}
            }
            i += 1;
        }
        false
    }

    fn parse_flow_seq(&mut self) -> Result<Node> {
        let _start = self.pos(self.s.idx);
        self.bump(); // '['
        let mut items = Vec::new();
        loop {
            self.skip_flow_ws();
            match self.cur() {
                Some(']') => {
                    self.bump();
                    break;
                }
                None => {
                    let p = self.pos(self.s.idx);
                    return self.err(p, "did not find expected ',' or ']'", None);
                }
                _ => {}
            }
            if self.cur() == Some(',') {
                // empty entry
                items.push(Node::Scalar {
                    raw: String::new(),
                    resolved: Resolved::Null,
                    style: ScalarStyle::Plain,
                });
                self.bump();
                continue;
            }
            let node = self.parse_node(None, true)?;
            items.push(node);
            self.skip_flow_ws();
            match self.cur() {
                Some(',') => {
                    self.bump();
                }
                Some(']') => {
                    self.bump();
                    break;
                }
                None => {
                    let p = self.pos(self.s.idx);
                    return self.err(p, "did not find expected ',' or ']'", None);
                }
                _ => {
                    let p = self.pos(self.s.idx);
                    return self.err(p, "did not find expected ',' or ']'", None);
                }
            }
        }
        Ok(Node::Seq(items))
    }

    fn parse_flow_map(&mut self) -> Result<Node> {
        let _start = self.pos(self.s.idx);
        self.bump(); // '{'
        let mut items: Vec<(String, Node)> = Vec::new();
        loop {
            self.skip_flow_ws();
            match self.cur() {
                Some('}') => {
                    self.bump();
                    break;
                }
                None => {
                    let p = self.pos(self.s.idx);
                    return self.err(p, "did not find expected ',' or '}'", None);
                }
                _ => {}
            }
            // key
            let key_node = self.parse_node(None, false)?;
            let key = match &key_node {
                Node::Scalar { raw, .. } => raw.clone(),
                Node::Seq(v) => serde_seq_key(v),
                Node::Map(v) => serde_map_key(v),
            };
            self.skip_flow_ws();
            let value = if self.cur() == Some(':') {
                self.bump();
                self.skip_flow_ws();
                match self.cur() {
                    Some(',') | Some('}') | None => Node::Scalar {
                        raw: String::new(),
                        resolved: Resolved::Null,
                        style: ScalarStyle::Plain,
                    },
                    _ => self.parse_node(None, true)?,
                }
            } else {
                Node::Scalar {
                    raw: String::new(),
                    resolved: Resolved::Null,
                    style: ScalarStyle::Plain,
                }
            };
            if items.iter().any(|(k, _)| k == &key) {
                return Err(Error::new(format!("duplicate entry with key {:?}", key)));
            }
            items.push((key, value));
            self.skip_flow_ws();
            match self.cur() {
                Some(',') => {
                    self.bump();
                }
                Some('}') => {
                    self.bump();
                    break;
                }
                None => {
                    let p = self.pos(self.s.idx);
                    return self.err(p, "did not find expected ',' or '}'", None);
                }
                _ => {
                    let p = self.pos(self.s.idx);
                    return self.err(p, "did not find expected ',' or '}'", None);
                }
            }
        }
        Ok(Node::Map(items))
    }

    fn skip_flow_ws(&mut self) -> bool {
        loop {
            match self.cur() {
                Some(c) if is_blank(c) => {
                    self.bump();
                }
                Some('#') => {
                    while let Some(c) = self.cur() {
                        if is_break(c) {
                            break;
                        }
                        self.bump();
                    }
                }
                _ => return !self.at_end(),
            }
        }
    }

    fn parse_block_seq(&mut self, indent: Option<usize>) -> Result<Node> {
        let mut items = Vec::new();
        loop {
            self.skip_to_content()?;
            if self.at_end() {
                break;
            }
            let line_indent = self.line_indent();
            if !self.is_block_seq_entry() {
                break;
            }
            if let Some(ind) = indent {
                if line_indent < ind {
                    break;
                }
            }
            self.bump(); // '-'
            // content on same line
            let content_indent = self.line_indent() + self.spaces_after_marker();
            self.skip_inline_ws();
            if self.at_end() || self.cur() == Some('#') {
                // value on following lines
                let node = self.parse_node(Some(content_indent + 1), true)?;
                items.push(node);
            } else {
                let node = self.parse_node(Some(content_indent + 1), true)?;
                items.push(node);
            }
        }
        Ok(Node::Seq(items))
    }

    fn parse_block_map(&mut self, indent: Option<usize>) -> Result<Node> {
        let start = self.pos(self.s.idx);
        let mut items: Vec<(String, Node)> = Vec::new();
        let mut first_indent: Option<usize> = indent;
        loop {
            self.skip_to_content()?;
            if self.at_end() {
                break;
            }
            let line_indent = self.line_indent();
            if let Some(ind) = first_indent {
                if line_indent < ind {
                    break;
                }
            } else {
                first_indent = Some(line_indent);
            }
            if !self.is_block_map_entry() {
                let p = self.pos(self.s.idx);
                return self.err(
                    p,
                    "did not find expected key",
                    Some(("while parsing a block mapping", start)),
                );
            }
            // parse the key
            let key_node = self.parse_key()?;
            let key = match &key_node {
                Node::Scalar { raw, .. } => raw.clone(),
                Node::Seq(v) => serde_seq_key(v),
                Node::Map(v) => serde_map_key(v),
            };
            // expect ':'
            self.skip_inline_ws();
            if self.cur() != Some(':') {
                let p = self.pos(self.s.idx);
                return self.err(
                    p,
                    "could not find expected ':'",
                    Some(("while scanning a simple key", start)),
                );
            }
            self.bump();
            // value
            self.skip_inline_ws();
            let same_line_value = !self.at_end() && !is_break(self.cur().unwrap());
            let value = if same_line_value {
                if self.cur() == Some('#') {
                    Node::Scalar {
                        raw: String::new(),
                        resolved: Resolved::Null,
                        style: ScalarStyle::Plain,
                    }
                } else {
                    let ind = self.line_indent();
                    self.parse_node(Some(ind + 1), true)?
                }
            } else {
                // value on following lines with greater indent
                let save = self.s.idx;
                self.skip_to_content()?;
                if self.at_end() || self.line_indent() <= line_indent {
                    self.s.idx = save;
                    Node::Scalar {
                        raw: String::new(),
                        resolved: Resolved::Null,
                        style: ScalarStyle::Plain,
                    }
                } else {
                    let ind = self.line_indent();
                    self.parse_node(Some(ind), true)?
                }
            };
            if items.iter().any(|(k, _)| k == &key) {
                return Err(Error::new(format!("duplicate entry with key {:?}", key)));
            }
            items.push((key, value));
        }
        Ok(Node::Map(items))
    }

    fn parse_key(&mut self) -> Result<Node> {
        match self.cur() {
            Some('"') => {
                let s = self.parse_double_quoted()?;
                Ok(Node::Scalar {
                    raw: s,
                    resolved: Resolved::Str,
                    style: ScalarStyle::DoubleQuoted,
                })
            }
            Some('\'') => {
                let s = self.parse_single_quoted()?;
                Ok(Node::Scalar {
                    raw: s,
                    resolved: Resolved::Str,
                    style: ScalarStyle::SingleQuoted,
                })
            }
            Some('[') => self.parse_flow_seq(),
            Some('{') => self.parse_flow_map(),
            _ => {
                let raw = self.read_plain_key()?;
                Ok(Node::Scalar {
                    raw,
                    resolved: Resolved::Str,
                    style: ScalarStyle::Plain,
                })
            }
        }
    }

    fn read_plain_key(&mut self) -> Result<String> {
        let mut out = String::new();
        loop {
            match self.cur() {
                None | Some('\n') | Some('\r') => break,
                Some(':') => break,
                Some('#') if !out.is_empty() && out.ends_with(' ') => break,
                Some(c) => {
                    out.push(c);
                    self.bump();
                }
            }
        }
        Ok(out.trim_end().to_string())
    }

    fn line_indent(&self) -> usize {
        let mut i = self.s.idx;
        let mut indent = 0;
        // walk back to line start
        while i > 0 && self.s.chars[i - 1] != '\n' {
            i -= 1;
        }
        while i < self.s.chars.len() {
            match self.s.chars[i] {
                ' ' => indent += 1,
                '\t' => indent += 1,
                '\n' => return indent,
                _ => return indent,
            }
            i += 1;
        }
        indent
    }

    fn spaces_after_marker(&self) -> usize {
        let mut i = self.s.idx;
        let mut n = 0;
        while i < self.s.chars.len() && is_space(self.s.chars[i]) {
            n += 1;
            i += 1;
        }
        n
    }

    fn skip_inline_ws(&mut self) {
        while let Some(c) = self.cur() {
            if is_space(c) {
                self.bump();
            } else {
                break;
            }
        }
    }

    fn skip_to_content(&mut self) -> bool {
        loop {
            match self.cur() {
                Some(c) if is_space(c) => {
                    self.bump();
                }
                Some('\n') => {
                    self.bump();
                }
                Some('\r') => {
                    self.bump();
                }
                Some('#') => {
                    while let Some(c) = self.cur() {
                        if is_break(c) {
                            break;
                        }
                        self.bump();
                    }
                }
                _ => return !self.at_end(),
            }
        }
    }

    fn parse_scalar(&mut self, indent: Option<usize>) -> Result<Node> {
        match self.cur() {
            Some('"') => {
                let s = self.parse_double_quoted()?;
                Ok(Node::Scalar {
                    resolved: Resolved::Str,
                    raw: s,
                    style: ScalarStyle::DoubleQuoted,
                })
            }
            Some('\'') => {
                let s = self.parse_single_quoted()?;
                Ok(Node::Scalar {
                    resolved: Resolved::Str,
                    raw: s,
                    style: ScalarStyle::SingleQuoted,
                })
            }
            _ => {
                let start = self.pos(self.s.idx);
                let (raw, style) = self.parse_plain(indent)?;
                if let Some(c) = self.cur() {
                    if !is_blank(c) && c != ',' && c != ']' && c != '}' && c != ':' {
                        return self.err(
                            start,
                            "found character that cannot start any token",
                            Some(("while scanning for the next token", start)),
                        );
                    }
                }
                let resolved = resolve_plain(&raw);
                Ok(Node::Scalar {
                    raw,
                    resolved,
                    style,
                })
            }
        }
    }

    fn parse_plain(&mut self, indent: Option<usize>) -> Result<(String, ScalarStyle)> {
        let mut lines: Vec<String> = Vec::new();
        let mut cur_line = String::new();
        let mut broke_on_flow = false;
        loop {
            match self.cur() {
                None => break,
                Some(c) if is_break(c) => {
                    self.bump();
                    break;
                }
                Some(',') | Some(']') | Some('}') | Some(':')
                    if indent.is_none() =>
                {
                    broke_on_flow = true;
                    break;
                }
                Some('#') if !cur_line.is_empty() && cur_line.ends_with(' ') => {
                    while let Some(c) = self.cur() {
                        if is_break(c) {
                            break;
                        }
                        self.bump();
                    }
                    break;
                }
                Some(c) => {
                    cur_line.push(c);
                    self.bump();
                }
            }
        }
        // trim trailing whitespace
        let cur = cur_line.trim_end().to_string();
        lines.push(cur);
        // multi-line plain scalars
        if !broke_on_flow {
            loop {
                let save = self.s.idx;
                // skip blank lines
                let mut blanks = 0;
                let mut saw_content = false;
                let mut line = String::new();
                let mut i = self.s.idx;
                // measure indentation of the next content line
                let mut ind = 0usize;
                while i < self.s.chars.len() {
                    match self.s.chars[i] {
                        ' ' | '\t' => {
                            ind += 1;
                            i += 1;
                        }
                        '\n' => {
                            blanks += 1;
                            ind = 0;
                            i += 1;
                        }
                        _ => {
                            saw_content = true;
                            break;
                        }
                    }
                }
                if !saw_content {
                    self.s.idx = i;
                    break;
                }
                if let Some(min_ind) = indent {
                    if ind <= min_ind - 1 {
                        self.s.idx = save;
                        break;
                    }
                }
                // collect the line
                while i < self.s.chars.len() {
                    let c = self.s.chars[i];
                    if c == '#' && line.ends_with(' ') {
                        break;
                    }
                    if is_break(c) {
                        break;
                    }
                    line.push(c);
                    i += 1;
                }
                if line.trim_end().is_empty() {
                    self.s.idx = save;
                    break;
                }
                let line = line.trim_end().to_string();
                if line.is_empty() {
                    self.s.idx = save;
                    break;
                }
                self.s.idx = i;
                lines.push("".repeat(blanks));
                lines.push(line);
            }
        }
        // fold
        let mut out = String::new();
        for (i, l) in lines.iter().enumerate() {
            if i == 0 {
                out.push_str(l);
            } else {
                if l.is_empty() {
                    out.push('\n');
                } else {
                    if !out.ends_with('\n') {
                        out.push(' ');
                    }
                    out.push_str(l);
                }
            }
        }
        Ok((out, ScalarStyle::Plain))
    }

    fn parse_single_quoted(&mut self) -> Result<String> {
        let start = self.pos(self.s.idx);
        self.bump(); // '
        let mut lines: Vec<String> = Vec::new();
        let mut cur = String::new();
        loop {
            match self.cur() {
                None => {
                    return self.err(
                        start,
                        "found unexpected end of stream",
                        Some(("while scanning a quoted scalar", start)),
                    )
                }
                Some('\'') => {
                    if self.peek(1) == Some('\'') {
                        cur.push('\'');
                        self.bump();
                        self.bump();
                    } else {
                        self.bump();
                        break;
                    }
                }
                Some(c) if is_break(c) => {
                    self.bump();
                    lines.push(std::mem::take(&mut cur));
                    // skip leading indentation of the next line
                    while let Some(c) = self.cur() {
                        if is_space(c) {
                            self.bump();
                        } else {
                            break;
                        }
                    }
                    continue;
                }
                Some(c) => {
                    cur.push(c);
                    self.bump();
                }
            }
        }
        lines.push(std::mem::take(&mut cur));
        let mut out = String::new();
        for (i, l) in lines.iter().enumerate() {
            if i == 0 {
                out.push_str(l);
            } else if l.is_empty() {
                out.push('\n');
            } else {
                if !out.ends_with('\n') {
                    out.push(' ');
                }
                out.push_str(l);
            }
        }
        // trim trailing spaces before breaks
        Ok(out.trim_end().to_string())
    }

    fn parse_double_quoted(&mut self) -> Result<String> {
        let start = self.pos(self.s.idx);
        self.bump(); // "
        let mut lines: Vec<String> = Vec::new();
        let mut cur = String::new();
        loop {
            match self.cur() {
                None => {
                    return self.err(
                        start,
                        "found unexpected end of stream",
                        Some(("while scanning a quoted scalar", start)),
                    )
                }
                Some('"') => {
                    self.bump();
                    break;
                }
                Some('\\') => {
                    self.bump();
                    match self.cur() {
                        None => {
                            return self.err(
                                start,
                                "found unknown escape character",
                                Some(("while parsing a quoted scalar", start)),
                            )
                        }
                        Some(c) => {
                            let ch = self.cur().unwrap();
                            match ch {
                                '0' => cur.push('\0'),
                                'a' => cur.push('\u{7}'),
                                'b' => cur.push('\u{8}'),
                                't' | '\t' => cur.push('\t'),
                                'n' => cur.push('\n'),
                                'v' => cur.push('\u{b}'),
                                'f' => cur.push('\u{c}'),
                                'r' => cur.push('\r'),
                                'e' => cur.push('\u{1b}'),
                                ' ' => cur.push(' '),
                                '"' => cur.push('"'),
                                '/' => cur.push('/'),
                                '\\' => cur.push('\\'),
                                'N' => cur.push('\u{85}'),
                                '_' => cur.push('\u{a0}'),
                                'L' => cur.push('\u{2028}'),
                                'P' => cur.push('\u{2029}'),
                                'x' | 'u' | 'U' => {
                                    self.bump();
                                    let n = match ch {
                                        'x' => 2,
                                        'u' => 4,
                                        _ => 8,
                                    };
                                    let mut v: u32 = 0;
                                    for _ in 0..n {
                                        match self.cur() {
                                            Some(d) if d.is_ascii_hexdigit() => {
                                                v = v * 16 + d.to_digit(16).unwrap();
                                                self.bump();
                                            }
                                            _ => {
                                                let p = self.pos(self.s.idx);
                                                return self.err(
                                                    p,
                                                    "did not find expected hexdecimal number",
                                                    Some(("while parsing a quoted scalar", start)),
                                                );
                                            }
                                        }
                                    }
                                    match char::from_u32(v) {
                                        Some(c) => cur.push(c),
                                        None => {
                                            let p = self.pos(self.s.idx);
                                            return self.err(
                                                p,
                                                "found invalid Unicode character escape code",
                                                Some(("while parsing a quoted scalar", start)),
                                            );
                                        }
                                    }
                                    continue;
                                }
                                c if is_break(c) => {
                                    self.bump();
                                    while let Some(c) = self.cur() {
                                        if is_space(c) {
                                            self.bump();
                                        } else {
                                            break;
                                        }
                                    }
                                    continue;
                                }
                                _ => {
                                    let p = self.pos(self.s.idx);
                                    return self.err(
                                        p,
                                        "found unknown escape character",
                                        Some(("while parsing a quoted scalar", start)),
                                    );
                                }
                            }
                            self.bump();
                        }
                    }
                }
                Some(c) if is_break(c) => {
                    self.bump();
                    lines.push(std::mem::take(&mut cur));
                    while let Some(c) = self.cur() {
                        if is_space(c) {
                            self.bump();
                        } else {
                            break;
                        }
                    }
                }
                Some(c) => {
                    cur.push(c);
                    self.bump();
                }
            }
        }
        lines.push(std::mem::take(&mut cur));
        let mut out = String::new();
        for (i, l) in lines.iter().enumerate() {
            if i == 0 {
                out.push_str(l);
            } else if l.is_empty() {
                out.push('\n');
            } else {
                if !out.ends_with('\n') {
                    out.push(' ');
                }
                out.push_str(l);
            }
        }
        Ok(out.trim_end().to_string())
    }

    fn parse_block_scalar(&mut self, indent: Option<usize>) -> Result<Node> {
        let style = if self.cur() == Some('|') {
            ScalarStyle::Literal
        } else {
            ScalarStyle::Folded
        };
        self.bump();
        let mut chomp = ' ';
        let mut explicit_indent: Option<usize> = None;
        while let Some(c) = self.cur() {
            match c {
                '-' | '+' => {
                    chomp = c;
                    self.bump();
                }
                '0'..='9' => {
                    let d = c.to_digit(10).unwrap() as usize;
                    explicit_indent = Some(d);
                    self.bump();
                }
                _ => break,
            }
        }
        // skip to end of line
        while let Some(c) = self.cur() {
            if is_break(c) {
                break;
            }
            self.bump();
        }
        let mut lines: Vec<String> = Vec::new();
        let mut base_indent: Option<usize> = explicit_indent.map(|i| i + indent.unwrap_or(0));
        loop {
            if self.at_end() {
                break;
            }
            // measure indent
            let mut i = self.s.idx;
            let mut ind = 0usize;
            let mut blank = true;
            while i < self.s.chars.len() {
                match self.s.chars[i] {
                    ' ' => {
                        ind += 1;
                        i += 1;
                    }
                    '\t' => {
                        ind += 1;
                        i += 1;
                    }
                    '\n' => {
                        lines.push(String::new());
                        i += 1;
                        break;
                    }
                    _ => {
                        blank = false;
                        break;
                    }
                }
            }
            if blank && i < self.s.chars.len() && self.s.chars[i] == '\n' {
                self.s.idx = i + 1;
                continue;
            }
            if blank && i >= self.s.chars.len() {
                self.s.idx = i;
                break;
            }
            let li = base_indent.unwrap_or(ind);
            if base_indent.is_none() {
                base_indent = Some(ind);
                if ind == 0 {
                    break;
                }
            }
            if ind < li {
                self.s.idx = i;
                break;
            }
            self.s.idx = i;
            let mut line = String::new();
            for _ in 0..(ind - li) {
                line.push(' ');
            }
            while let Some(c) = self.cur() {
                if is_break(c) {
                    break;
                }
                line.push(c);
                self.bump();
            }
            if self.cur() == Some('\n') {
                self.bump();
            }
            lines.push(line);
        }
        // join
        let mut out = String::new();
        match style {
            ScalarStyle::Literal => {
                for l in &lines {
                    out.push_str(l);
                    out.push('\n');
                }
            }
            _ => {
                let mut first = true;
                let mut prev_more = false;
                for l in &lines {
                    if first {
                        out.push_str(l);
                        first = false;
                        continue;
                    }
                    if l.starts_with(' ') || prev_more {
                        out.push('\n');
                        out.push_str(l);
                    } else if l.is_empty() {
                        out.push('\n');
                    } else {
                        out.push(' ');
                        out.push_str(l);
                    }
                    prev_more = l.starts_with(' ');
                }
                if chomp != '-' {
                    out.push('\n');
                }
            }
        }
        if chomp == '-' && style == ScalarStyle::Literal {
            while out.ends_with('\n') {
                out.pop();
            }
        }
        let resolved = Resolved::Str;
        Ok(Node::Scalar {
            raw: out,
            resolved,
            style,
        })
    }
}

fn serde_seq_key(v: &[Node]) -> String {
    // serde maps complex keys to their Debug-ish representation
    format!("{:?}", v.len())
}

fn serde_map_key(v: &[(String, Node)]) -> String {
    format!("{:?}", v.len())
}

fn apply_tag(tag: String, node: Node) -> Node {
    match tag.as_str() {
        "!!str" | "!str" => match node {
            Node::Scalar { raw, style, .. } => Node::Scalar {
                raw,
                resolved: Resolved::Str,
                style,
            },
            other => other,
        },
        "!!int" | "!int" => match node {
            Node::Scalar { raw, style, .. } => Node::Scalar {
                raw: raw.clone(),
                resolved: parse_int(&raw).unwrap_or(Resolved::Str),
                style,
            },
            other => other,
        },
        "!!float" | "!float" => match node {
            Node::Scalar { raw, style, .. } => Node::Scalar {
                raw: raw.clone(),
                resolved: parse_float(&raw).unwrap_or(Resolved::Str),
                style,
            },
            other => other,
        },
        "!!bool" | "!bool" => match node {
            Node::Scalar { raw, style, .. } => Node::Scalar {
                raw: raw.clone(),
                resolved: parse_bool(&raw).unwrap_or(Resolved::Str),
                style,
            },
            other => other,
        },
        "!!null" | "!null" => match node {
            Node::Scalar { raw, style, .. } => Node::Scalar {
                raw,
                resolved: Resolved::Null,
                style,
            },
            other => other,
        },
        _ => node,
    }
}

pub fn resolve_plain(raw: &str) -> Resolved {
    if raw.is_empty() {
        return Resolved::Null;
    }
    match raw {
        "~" | "null" | "Null" | "NULL" => return Resolved::Null,
        "true" | "True" | "TRUE" => return Resolved::Bool(true),
        "false" | "False" | "FALSE" => return Resolved::Bool(false),
        _ => {}
    }
    if let Some(r) = parse_int(raw) {
        return r;
    }
    if let Some(r) = parse_float(raw) {
        return r;
    }
    Resolved::Str
}

fn parse_bool(raw: &str) -> Option<Resolved> {
    match raw {
        "true" | "True" | "TRUE" | "y" | "Y" | "yes" | "Yes" | "YES" | "on" | "On" | "ON" => {
            Some(Resolved::Bool(true))
        }
        "false" | "False" | "FALSE" | "n" | "N" | "no" | "No" | "NO" | "off" | "Off" | "OFF" => {
            Some(Resolved::Bool(false))
        }
        _ => None,
    }
}

fn parse_int(raw: &str) -> Option<Resolved> {
    let s = raw.trim();
    if s.is_empty() {
        return None;
    }
    let (neg, body) = if let Some(r) = s.strip_prefix('-') {
        (true, r)
    } else if let Some(r) = s.strip_prefix('+') {
        (false, r)
    } else {
        (false, s)
    };
    if body.starts_with("0x") || body.starts_with("0X") {
        let digits = &body[2..];
        if digits.is_empty() || !digits.chars().all(|c| c.is_ascii_hexdigit()) {
            return None;
        }
        let v = i64::from_str_radix(digits, 16).ok()?;
        return Some(Resolved::Int(if neg { -v } else { v }));
    }
    if !body.chars().all(|c| c.is_ascii_digit()) {
        return None;
    }
    let v: i64 = body.parse().ok()?;
    Some(Resolved::Int(if neg { -v } else { v }))
}

fn parse_float(raw: &str) -> Option<Resolved> {
    let s = raw.trim();
    if s.is_empty() {
        return None;
    }
    if !s.chars().any(|c| c == '.' || c == 'e' || c == 'E') {
        return None;
    }
    let v: f64 = s.parse().ok()?;
    if !v.is_finite() {
        return None;
    }
    Some(Resolved::Float(v))
}
