        let (line, col) = self.s.line_col(idx);
        Pos { idx, line, col }
    }'''
new_posfn = '''    fn pos(&self, idx: usize) -> Pos {
        let (line, col) = self.s.line_col(idx);
        Pos { line, col }
    }'''
assert old_posfn in s
s = s.replace(old_posfn, new_posfn)

# 3. Rewrite Node::Scalar construction sites
def scalar_repl(m):
    raw, resolved, style = m.group('raw'), m.group('resolved'), m.group('style')
    return f'Node::scalar({raw}, {resolved}, {style}, pos)'

pat_multi = re.compile(
    r'Node::Scalar \{\s*\n\s*raw: (?P<raw>[^,\n]*),\s*\n\s*resolved: (?P<resolved>[^,\n]*),\s*\n\s*style: (?P<style>[^,\n]*),\s*\n\s*\}',
    re.S)
pat_one = re.compile(
    r'Node::Scalar \{ raw: (?P<raw>[^,]*), resolved: (?P<resolved>[^,]*), style: (?P<style>[^}]*) \}')
s = pat_multi.sub(scalar_repl, s)
s = pat_one.sub(scalar_repl, s)

# 4. Seq / Map constructions
s = s.replace('Ok(Node::Seq(items))', 'Ok(Node::seq(items, seq_pos))')
s = s.replace('Ok(Node::Map(items))', 'Ok(Node::map(items, map_pos))')
s = s.replace('items.push(node);', 'items.push(node);')

open('src/yaml.rs','w').write(s)
print("ok")
