//! Converting parsed YAML nodes into an ordered JSON tree, mirroring what
//! serde_yaml + serde_json would do.

use crate_dep::Value;

pub use crate_dep::Map;

use crate::yaml::{Kind, Node, Pos, Resolved};

#[derive(Debug, Clone)]
pub struct YamlError {
    pub path: String,
    pub pos: Option<Pos>,
    pub msg: String,
}

impl std::fmt::Display for YamlError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        if self.path.is_empty() && self.pos.is_none() {
            write!(f, "{}", self.msg)
        } else {
            match &self.pos {
                Some(p) => write!(
                    f,
                    "{}: {} at line {} column {}",
                    self.path,
                    self.msg,
                    p.line1(),
                    p.col1()
                ),
                None => write!(f, "{}: {}", self.path, self.msg),
            }
        }
    }
}

type R<T> = std::result::Result<T, YamlError>;

fn err<T>(path: &str, pos: Option<Pos>, msg: String) -> R<T> {
    Err(YamlError {
        path: path.to_string(),
        pos,
        msg,
    })
}

/// Formats a float the way serde does (`Unexpected::Float` / ryu).
pub fn fmt_float(v: f64) -> String {
    let mut buf = ryu::Buffer::new();
    let s = buf.format(v);
    // serde prints e.g. `1000.0`, ryu gives `1000.0`
    s.to_string()
}

fn join(path: &str, key: &str) -> String {
    if path.is_empty() {
        key.to_string()
    } else {
        format!("{}.{}", path, key)
    }
}

fn index(path: &str, idx: usize) -> String {
    if path.is_empty() {
        format!(".[{}]", idx)
    } else {
        format!("{}[{}]", path, idx)
    }
}

fn node_to_value(path: &str, node: &Node) -> R<Value> {
    match &node.kind {
        Kind::Scalar { raw, resolved, .. } => Ok(match resolved {
            Resolved::Null => Value::Null,
            Resolved::Bool(b) => Value::Bool(*b),
            Resolved::Int(i) => {
                if *i >= i64::MIN as i64 && *i <= i64::MAX as i64 {
                    Value::Number(Number::from(*i))
                } else {
                    return err(
                        path,
                        Some(node.pos),
                        format!(
                            "invalid type: integer `{}` as u128, expected any YAML value",
                            raw
                        ),
                    );
                }
            }
            Resolved::Float(f) => {
                if f.is_finite() {
                    Value::Number(Number::from_f64(*f))
                } else {
                    Value::Null
                }
            }
            Resolved::Str => Value::String(raw.clone()),
        }),
        Kind::Seq(items) => {
            let mut out = Vec::with_capacity(items.len());
            for (i, n) in items.iter().enumerate() {
                out.push(node_to_value(&index(path, i), n)?);
            }
            Ok(Value::Array(out))
        }
        Kind::Map(items) => {
            let mut out = Map::new();
            for (k, v) in items.iter() {
                let p = join(path, k);
                if out.contains_key(k) {
                    return err(
                        &p,
                        Some(v.pos),
                        format!("duplicate entry with key {:?}", k),
                    );
                }
                out.insert(k.clone(), node_to_value(&p, v)?);
            }
            Ok(Value::Object(out))
        }
    }
}

pub fn to_value(node: &Node) -> R<Value> {
    node_to_value("", node)
}

pub fn to_json(node: &Node) -> R<String> {
    let v = to_value(node)?;
    Ok(serde_json::to_string(&v).unwrap_or_else(|_| "null".to_string()))
}
