{"command": "cd /workspace && cat > src/jf.rs <<'RSEOF'
//! The `jf`-style template expansion used by `-m` / `--pipe-msg-in`.

#[derive(Debug, Clone, PartialEq)]
pub enum JfError {
    /// Unknown placeholder at the given 1-based column.
    InvalidPlaceholder(char, usize),
    /// The template ended in the middle of a placeholder.
    IncompletePlaceholder,
    /// A placeholder has no value left.
    MissingValue(usize),
    /// More values than placeholders.
    TooManyValues,
}

impl std::fmt::Display for JfError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            JfError::InvalidPlaceholder(c, col) => write!(
                f,
                "invalid placeholder '%{}' at column {}, use one of '%s' or '%q', or escape it using '%%'",
                c, col
            ),
            JfError::IncompletePlaceholder => {
                write!(f, "template ended with incomplete placeholder")
            }
            JfError::MissingValue(col) => write!(f, "placeholder missing value at column {}", col),
            JfError::TooManyValues => write!(
                f,
                "too many positional values, not enough positional placeholders"
            ),
        }
    }
}

fn quote_yaml(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\u{0}' => out.push_str("\\0"),
            '\u{7}' => out.push_str("\\a"),
            '\u{8}' => out.push_str("\\b"),
            '\t' => out.push_str("\\t"),
            '\n' => out.push_str("\\n"),
            '\u{b}' => out.push_str("\\v"),
            '\u{c}' => out.push_str("\\f"),
            '\r' => out.push_str("\\r"),
            '\u{1b}' => out.push_str("\\e"),
            c if (c as u32) < 0x20 => {
                out.push_str(&format!("\\x{:02x}", c as u32));
            }
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

pub fn count_placeholders(fmt: &str) -> Result<usize, JfError> {
    let chars: Vec<char> = fmt.chars().collect();
    let mut count = 0usize;
    let mut i = 0usize;
    while i < chars.len() {
        if chars[i] == '%' {
            match chars.get(i + 1) {
                None => return Err(JfError::IncompletePlaceholder),
                Some('%') => {
                    i += 2;
                    continue;
                }
                Some('s') | Some('q') => {
                    count += 1;
                    i += 2;
                    continue;
                }
                Some(c) => return Err(JfError::InvalidPlaceholder(*c, i + 1)),
            }
        }
        i += 1;
    }
    Ok(count)
}

pub fn expand(fmt: &str, values: &[String]) -> Result<String, JfError> {
    let placeholders = count_placeholders(fmt)?;
    if values.len() > placeholders {
        return Err(JfError::TooManyValues);
    }
    let chars: Vec<char> = fmt.chars().collect();
    let mut out = String::new();
    let mut idx = 0usize;
    let mut i = 0usize;
    while i < chars.len() {
        if chars[i] == '%' {
            match chars.get(i + 1) {
                None => return Err(JfError::IncompletePlaceholder),
                Some('%') => {
                    out.push('%');
                    i += 2;
                    continue;
                }
                Some('s') => {
                    let v = values.get(idx).ok_or(JfError::MissingValue(i + 1))?;
                    idx += 1;
                    out.push_str(v);
                    i += 2;
                    continue;
                }
                Some('q') => {
                    let v = values.get(idx).ok_or(JfError::MissingValue(i + 1))?;
                    idx += 1;
                    out.push_str(&quote_yaml(v));
                    i += 2;
                    continue;
                }
                Some(c) => return Err(JfError::InvalidPlaceholder(*c, i + 1)),
            }
        }
        out.push(chars[i]);
        i += 1;
    }
    Ok(out)
}
RSEOF
echo ok"}

