            return None;
        }
        let v = u64::from_str_radix(digits, 16).ok()?;
        if neg {
            if v <= (i64::MAX as u64) + 1 {
                return Some(Resolved::Int((v as i128 * -1) as i64));
            }
        } else if v <= i64::MAX as u64 {
            return Some(Resolved::Int(v as i64));
        } else {
            return Some(Resolved::UInt(v));
        }
    }
    if !body.chars().all(|c| c.is_ascii_digit()) {
        return None;
    }
    if neg {
        if let Ok(v) = body.parse::<i64>() {
            return Some(Resolved::Int(-v));
        }
    } else if let Ok(v) = body.parse::<i64>() {
        return Some(Resolved::Int(v));
    } else if let Ok(v) = body.parse::<u64>() {
        return Some(Resolved::UInt(v));
    }
    Some(Resolved::Big {
        raw: raw.to_string(),
        signed: neg,
    })
}'''
