fn str_of(node: &Node, path: &str) -> R<String> {
    match &node.kind {
        Kind::Scalar { raw, .. } => Ok(raw.clone()),
        _ => expected(node, path, "a string"),
    }
}

fn usize_of(node: &Node, path: &str) -> R<usize> {
    match &node.kind {
        Kind::Scalar { resolved, .. } => match resolved {
            Resolved::Int(i) if *i >= 0 => Ok(*i as usize),
            Resolved::UInt(u) => Ok(*u as usize),
            Resolved::Big { .. } => expected(node, path, "usize"),
            Resolved::Int(_) => expected(node, path, "usize"),
            _ => expected(node, path, "usize"),
        },
        _ => expected(node, path, "usize"),
    }
}

fn bool_of(node: &Node, path: &str) -> R<bool> {
    match &node.kind {
        Kind::Scalar { resolved, .. } => match resolved {
            Resolved::Bool(b) => Ok(*b),
            _ => expected(node, path, "a boolean"),
        },
        _ => expected(node, path, "a boolean"),
    }
}

fn command_of(node: &Node, path: &str) -> R<Command> {
    match &node.kind {
        Kind::Map(items) => {
            let mut command: Option<String> = None;
            let mut args: Option<Vec<String>> = None;
            for (k, v) in items.iter() {
                let sub = format!("{}.{}", path, k);
                match k.as_str() {
                    "command" => command = Some(str_of(v, &sub)?),
                    "args" => {
                        match &v.kind {
                            Kind::Seq(elems) => {
                                let mut out = Vec::new();
                                for (i, e) in elems.iter().enumerate() {
                                    out.push(str_of(e, &format!("{}[{}]", sub, i))?);
                                }
                                args = Some(out);
                            }
                            _ => return expected(v, &sub, "a sequence"),
                        }
                    }
                    other => {
                        return Err(MsgError {
                            path: path.to_string(),
                            pos: Some(v.pos),
                            msg: format!(
                                "unknown field `{}`, expected `command` or `args`",
                                other
                            ),
                        })
                    }
                }
            }
            match command {
                Some(c) => Ok(Command { command: c, args }),
                None => Err(MsgError {
                    path: path.to_string(),
                    pos: Some(node.pos),
                    msg: "missing field `command`".to_string(),
                }),
            }
        }
        _ => expected(node, path, "struct Command"),
    }
}

fn filter_of(node: &Node, path: &str) -> R<NodeFilter> {
    match &node.kind {
        Kind::Scalar { raw, .. } => {
            let s = raw.clone();
            parse_filter(&s).ok_or_else(|| unknown_variant_enum(&s, FILTER_NAMES, "NodeFilter"))
        }
        Kind::Map(items) => {
            if items.len() != 1 {
                return Err(MsgError {
                    path: path.to_string(),
                    pos: None,
                    msg: "invalid value: map, expected map with a single key".to_string(),
                });
            }
            let (k, v) = &items[0];
            if parse_filter(k).is_some() {
                // unit variant with a value
                return Err(MsgError {
                    path: path.to_string(),
                    pos: Some(v.pos),
                    msg: "invalid type: map, expected unit variant".to_string(),
                });
            }
            Err(unknown_variant_enum(k, FILTER_NAMES, "NodeFilter"))
        }
        _ => expected(node, path, "enum NodeFilter"),
    }
}

fn sorter_of(node: &Node, path: &str) -> R<NodeSorter> {
    match &node.kind {
        Kind::Scalar { raw, .. } => {
            let s = raw.clone();
            parse_sorter(&s).ok_or_else(|| unknown_variant_enum(&s, SORTER_NAMES, "NodeSorter"))
        }
        Kind::Map(items) => {
            if items.len() != 1 {
                return Err(MsgError {
                    path: path.to_string(),
                    pos: None,
                    msg: "invalid value: map, expected map with a single key".to_string(),
                });
            }
            let (k, v) = &items[0];
            if parse_sorter(k).is_some() {
                return Err(MsgError {
                    path: path.to_string(),
                    pos: Some(v.pos),
                    msg: "invalid type: map, expected unit variant".to_string(),
                });
            }
            Err(unknown_variant_enum(k, SORTER_NAMES, "NodeSorter"))
        }
        _ => expected(node, path, "enum NodeSorter"),
    }
}

fn input_op_of(node: &Node, path: &str) -> R<InputOperation> {
    match &node.kind {
        Kind::Scalar { raw, .. } => match raw.as_str() {
            "GoToPreviousCharacter" => Ok(InputOperation::GoToPreviousCharacter),
            "GoToNextCharacter" => Ok(InputOperation::GoToNextCharacter),
            "GoToPreviousWord" => Ok(InputOperation::GoToPreviousWord),
            "GoToNextWord" => Ok(InputOperation::GoToNextWord),
            "GoToStart" => Ok(InputOperation::GoToStart),
            "GoToEnd" => Ok(InputOperation::GoToEnd),
            "DeletePreviousCharacter" => Ok(InputOperation::DeletePreviousCharacter),
            "DeleteNextCharacter" => Ok(InputOperation::DeleteNextCharacter),
            "DeletePreviousWord" => Ok(InputOperation::DeletePreviousWord),
            "DeleteNextWord" => Ok(InputOperation::DeleteNextWord),
            "DeleteLine" => Ok(InputOperation::DeleteLine),
            "DeleteTillEnd" => Ok(InputOperation::DeleteTillEnd),
            "SetCursor" | "InsertCharacter" => err_nopos(
                "invalid type: unit variant, expected newtype variant".to_string(),
            ),
            other => Err(unknown_variant_enum(other, INPUT_OP_NAMES, "InputOperation")),
        },
        Kind::Map(items) => {
            if items.len() != 1 {
                return Err(MsgError {
                    path: path.to_string(),
                    pos: None,
                    msg: "invalid value: map, expected map with a single key".to_string(),
                });
            }
            let (k, v) = &items[0];
            match k.as_str() {
                "SetCursor" => Ok(InputOperation::SetCursor(usize_of(v, path)?)),
                "InsertCharacter" => Ok(InputOperation::InsertCharacter(str_of(v, path)?)),
                other => Err(unknown_variant_enum(other, INPUT_OP_NAMES, "InputOperation")),
            }
        }
        _ => expected(node, path, "enum InputOperation"),
    }
}

fn filter_app_of(node: &Node, path: &str) -> R<NodeFilterApplicableDeserializer> {
    match &node.kind {
        Kind::Map(items) => {
            let mut filter: Option<NodeFilter> = None;
            let mut input: Option<String> = None;
            for (k, v) in items.iter() {
                let sub = format!("{}.{}", path, k);
                match k.as_str() {
                    "filter" => filter = Some(filter_of(v, &sub)?),
                    "input" => input = Some(str_of(v, &sub)?),
                    other => {
                        return Err(MsgError {
                            path: path.to_string(),
                            pos: Some(v.pos),
                            msg: format!(
                                "unknown field `{}`, expected `filter` or `input`",
                                other
                            ),
                        })
                    }
                }
            }
            match (filter, input) {
                (Some(f), Some(i)) => Ok(NodeFilterApplicableDeserializer { filter: f, input: i }),
                (None, _) => Err(MsgError {
                    path: path.to_string(),
                    pos: Some(node.pos),
                    msg: "missing field `filter`".to_string(),
                }),
                (_, None) => Err(MsgError {
                    path: path.to_string(),
                    pos: Some(node.pos),
                    msg: "missing field `input`".to_string(),
                }),
            }
        }
        _ => expected(node, path, "struct NodeFilterApplicableDeserializer"),
    }
}

fn sorter_app_of(node: &Node, path: &str) -> R<NodeSorterApplicable> {
    match &node.kind {
        Kind::Map(items) => {
            let mut sorter: Option<NodeSorter> = None;
            let mut reverse = false;
            for (k, v) in items.iter() {
                let sub = format!("{}.{}", path, k);
                match k.as_str() {
                    "sorter" => sorter = Some(sorter_of(v, &sub)?),
                    "reverse" => reverse = bool_of(v, &sub)?,
                    other => {
                        return Err(MsgError {
                            path: path.to_string(),
                            pos: Some(v.pos),
                            msg: format!(
                                "unknown field `{}`, expected `sorter` or `reverse`",
                                other
                            ),
                        })
                    }
                }
            }
            match sorter {
                Some(s) => Ok(NodeSorterApplicable {
                    sorter: s,
                    reverse,
                }),
                None => Err(MsgError {
                    path: path.to_string(),
                    pos: Some(node.pos),
                    msg: "missing field `sorter`".to_string(),
                }),
            }
        }
        _ => expected(node, path, "struct NodeSorterApplicable"),
    }
}

