//! Deserializing messages straight from parsed YAML nodes (the path used by
//! `--on-load` and by the `msg_in` pipe).

use crate::msg::*;
use crate::yaml::{Kind, Node, Pos, Resolved};

#[derive(Debug, Clone)]
pub struct MsgError {
    pub path: String,
    pub pos: Option<Pos>,
    pub msg: String,
}

impl std::fmt::Display for MsgError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        if self.path.is_empty() && self.pos.is_none() {
            write!(f, "{}", self.msg)
        } else {
            match &self.pos {
                Some(p) => write!(
                    f,
                    "{}: {} at line {} column {}",
                    self.path,
                    self.msg,
                    p.line1(),
                    p.col1()
                ),
                None => write!(f, "{}: {}", self.path, self.msg),
            }
        }
    }
}

type R<T> = std::result::Result<T, MsgError>;

fn err<T>(path: &str, node: &Node, msg: String) -> R<T> {
    Err(MsgError {
        path: path.to_string(),
        pos: Some(node.pos),
        msg,
    })
}

fn err_nopos<T>(msg: String) -> R<T> {
    Err(MsgError {
        path: String::new(),
        pos: None,
        msg,
    })
}

/// Formats a float like serde's `Unexpected::Float` does in this code path.
pub fn fmt_float(v: f64) -> String {
    let s = format!("{}", v);
    if v.is_finite() && !s.contains('.') {
        format!("{}.0", s)
    } else {
        s
    }
}

fn unexpected(node: &Node) -> String {
    match &node.kind {
        Kind::Scalar { resolved, raw, .. } => match resolved {
            Resolved::Null => "unit value".to_string(),
            Resolved::Bool(b) => format!("boolean `{}`", b),
            Resolved::Int(i) => format!("integer `{}`", i),
            Resolved::UInt(u) => format!("integer `{}`", u),
            Resolved::Big { raw, signed } => format!(
                "integer `{}` as {}",
                raw,
                if *signed { "i128" } else { "u128" }
            ),
            Resolved::Float(f) => format!("floating point `{}`", fmt_float(*f)),
            Resolved::Str => format!("string {:?}", raw),
        },
        Kind::Seq(_) => "sequence".to_string(),
        Kind::Map(_) => "map".to_string(),
    }
}

fn expected(node: &Node, path: &str, exp: &str) -> R<String> {
    Err(MsgError {
        path: path.to_string(),
        pos: Some(node.pos),
        msg: format!("invalid type: {}, expected {}", unexpected(node), exp),
    })
}

fn unexp_plain(node: &Node, exp: &str) -> R<String> {
    Err(MsgError {
        path: String::new(),
        pos: None,
        msg: format!("invalid type: {}, expected {}", unexpected(node), exp),
    })
}

fn key_of(node: &Node) -> &str {
    match &node.kind {
        Kind::Scalar { raw, .. } => raw,
        Kind::Seq(_) => "",
        Kind::Map(_) => "",
    }
}

