pub fn from_node(node: &Node, empty: bool) -> R<Message> {
    if empty {
        return unexp_plain(node, "enum ExternalMsg").map(|_| unreachable!()).map_err(|mut e| {
            e.msg = "invalid type: Option value, expected enum ExternalMsg".to_string();
            e
        });
    }
    match &node.kind {
        Kind::Scalar { raw, resolved, .. } => match resolved {
            Resolved::Str => {
                let name = raw.clone();
                dispatch(&name, None, node)
            }
            Resolved::Null => unexp_plain(node, "enum ExternalMsg").map(|_| unreachable!()),
            _ => unexp_plain(node, "enum ExternalMsg").map(|_| unreachable!()),
        },
        Kind::Seq(_) => unexp_plain(node, "enum ExternalMsg").map(|_| unreachable!()),
        Kind::Map(items) => {
            if items.len() != 1 {
                return err_nopos("invalid value: map, expected map with a single key".to_string());
            }
            let (k, v) = &items[0];
            dispatch(k, Some(v.as_ref()), v)
        }
    }
}

/// Builds a `Message` for a tag name, optionally with the associated value.
fn dispatch(tag: &str, value: Option<&Node>, vnode: &Node) -> R<Message> {
    use Message as M;
    let unit = |m: M| -> R<Message> {
        match value {
            None => Ok(m),
            Some(_) => err_nopos("invalid type: map, expected unit variant".to_string()),
        }
    };
    let string = |m: fn(String) -> M| -> R<Message> {
        match value {
            None => err_nopos("invalid type: unit variant, expected newtype variant".to_string()),
            Some(v) => Ok(m(str_of(v, tag)?)),
        }
    };
    let usize_ = |m: fn(usize) -> M| -> R<Message> {
        match value {
            None => err_nopos("invalid type: unit variant, expected newtype variant".to_string()),
            Some(v) => Ok(m(usize_of(v, tag)?)),
        }
    };
    let cmd = |m: fn(Command) -> M| -> R<Message> {
        match value {
            None => err_nopos("invalid type: unit variant, expected newtype variant".to_string()),
            Some(v) => Ok(m(command_of(v, tag)?)),
