#[derive(Debug, Clone, Copy, PartialEq)]
pub enum PipeMsgIn {
    /// `-m`: pass the message to the active session.
    Pipe,
    /// `-M`: print the message instead.
    Print,
}

#[derive(Debug, Default)]
pub struct Args {
    pub stdin: bool,
    pub end_of_flags: bool,
    pub force_focus: bool,
    pub print_pwd_as_result: bool,
    pub read_only: bool,
    pub read0: bool,
    pub write0: bool,
    pub help: bool,
    pub version: bool,
    pub config: Option<String>,
    pub extra_config: Vec<String>,
    pub on_load: Vec<Message>,
    pub vroot: Option<String>,
    pub path: Option<String>,
    pub selection: Vec<String>,
    pub pipe_msg_in: Option<PipeMsgIn>,
    pub pipe_msg_format: Option<String>,
    pub pipe_msg_values: Vec<String>,
    /// (kind, raw path) in command line order
    pub paths: Vec<(u8, String)>,
}

/// Kinds used for `paths` ordering.
pub const P_CONFIG: u8 = 0;
pub const P_EXTRA_CONFIG: u8 = 1;
pub const P_VROOT: u8 = 2;
pub const P_PATH: u8 = 3;
pub const P_SELECTION: u8 = 4;

pub enum Action {
    Print(String),
    Run(Box<Args>),
}

pub struct CliError(pub String);

pub fn parse() -> Result<Action, CliError> {
    let argv: Vec<String> = std::env::args().collect();
    parse_from(&argv[1..])
}

fn parse_from(argv: &[String]) -> Result<Action, CliError> {
    let mut args = Args::default();
    let mut i = 0usize;
    let mut after_dashdash = false;
    while i < argv.len() {
        let a = &argv[i];
        i += 1;
        if !after_dashdash && a == "--" {
            after_dashdash = true;
            continue;
        }
        if !after_dashdash && args.pipe_msg_in.is_some() {
            // everything after the format is a template value
            if args.pipe_msg_format.is_none() {
                args.pipe_msg_format = Some(a.clone());
            } else {
                args.pipe_msg_values.push(a.clone());
            }
            continue;
        }
        if !after_dashdash && a.starts_with('-') && a != "-" {
            match a.as_str() {
                "-h" | "--help" => {
                    args.help = true;
                    continue;
                }
                "-V" | "--version" => {
                    args.version = true;
                    continue;
                }
                "-c" | "--config" => {
                    let v = next_arg(argv, &mut i);
                    args.config = Some(v.clone());
                    args.paths.push((P_CONFIG, v));
                    continue;
                }
                "-C" | "--extra-config" => {
                    let v = next_arg(argv, &mut i);
                    args.extra_config.push(v.clone());
                    args.paths.push((P_EXTRA_CONFIG, v));
                    continue;
                }
                "--vroot" => {
                    let v = next_arg(argv, &mut i);
                    args.vroot = Some(v.clone());
                    args.paths.push((P_VROOT, v));
                    continue;
                }
                "--on-load" => {
                    let v = next_arg(argv, &mut i);
                    match parse_message_arg(&v) {
                        Ok(m) => args.on_load.push(m),
                        Err(e) => return Err(CliError(e)),
                    }
                    continue;
                }
                "-m" | "--pipe-msg-in" => {
                    args.pipe_msg_in = Some(PipeMsgIn::Pipe);
                    continue;
                }
                "-M" | "--print-msg-in" => {
                    args.pipe_msg_in = Some(PipeMsgIn::Print);
                    continue;
                }
                "--force-focus" => {
                    args.force_focus = true;
                    continue;
                }
                "--print-pwd-as-result" => {
                    args.print_pwd_as_result = true;
                    continue;
                }
                "--read-only" => {
                    args.read_only = true;
                    continue;
                }
                "--read0" => {
                    args.read0 = true;
                    continue;
                }
                "--write0" => {
                    args.write0 = true;
                    continue;
                }
                "-0" | "--null" => {
                    args.read0 = true;
                    args.write0 = true;
                    continue;
                }
                _ => {
                    return Err(CliError(format!(
                        "invalid argument: {:?}, try `-- {:?}` or `--help`",
                        a, a
                    )))
                }
            }
        }
        // positional
        if args.path.is_none() {
            args.path = Some(a.clone());
            args.paths.push((P_PATH, a.clone()));
        } else {
            args.selection.push(a.clone());
            args.paths.push((P_SELECTION, a.clone()));
        }
    }
    // validate paths in command line order
    for (_kind, p) in args.paths.iter() {
        if p.is_empty() {
            return Err(CliError("empty string passed".to_string()));
        }
        let abs = crate::path::absolutize(p);
        if !crate::path::exists(&abs) {
            return Err(CliError(format!("path doesn't exist: {}", abs)));
        }
    }
    if args.help {
        return Ok(Action::Print(HELP.to_string()));
    }
    if args.version {
        return Ok(Action::Print(format!("xplr {}\n", VERSION)));
    }
    if let Some(mode) = args.pipe_msg_in {
        let format = args.pipe_msg_format.clone().unwrap_or_default();
        let expanded = match jf::expand(&format, &args.pipe_msg_values) {
            Ok(s) => s,
            Err(e) => return Err(CliError(format!("xplr -m: {}", e))),
        };
        let message = match crate::msgout::parse_yaml_message(&expanded) {
            Ok(m) => m,
            Err(e) => return Err(CliError(e)),
        };
        match mode {
