cat > src/msgout.rs <<'RSEOF'
//! Parsing messages from a JSON document (the `-m` / `-M` code path).

use crate::msg::Message;

/// serde reports floats with an explicit `+` in the exponent, the code path we
/// mimic uses serde_json's serialization format instead.
fn fix_float(msg: &str) -> String {
    if !msg.contains("floating point `") {
        return msg.to_string();
    }
    let mut out = String::with_capacity(msg.len());
    let mut rest = msg;
    while let Some(i) = rest.find("floating point `") {
        let start = i + "floating point `".len();
        let end = match rest[start..].find('`') {
            Some(e) => start + e,
            None => rest.len(),
        };
        out.push_str(&rest[..start]);
        let num = &rest[start..end];
        out.push_str(&num.replace("e+", "e"));
        out.push('`');
        rest = &rest[end + 1..];
    }
    out.push_str(rest);
    out
}

pub fn message_from_json(json: &str) -> Result<Message, String> {
    serde_json::from_str::<Message>(json).map_err(|e| fix_float(&e.to_string()))
}
RSEOF
echo ok"}

