//! Path helpers.

use std::path::{Path, PathBuf};

/// Turns a path into an absolute, lexically normalized path.
pub fn absolutize(p: &str) -> String {
    let path = Path::new(p);
    let mut buf = PathBuf::new();
    if path.is_absolute() {
        buf.push("/");
    } else {
        buf.push(std::env::current_dir().unwrap_or_default());
    }
    for c in path.components() {
        match c {
            std::path::Component::CurDir => {}
            std::path::Component::ParentDir => {
                buf.pop();
            }
            std::path::Component::RootDir => {
                buf = PathBuf::from("/");
            }
            other => buf.push(other.as_os_str()),
        }
    }
    buf.to_string_lossy().to_string()
}

pub fn exists(p: &str) -> bool {
    std::fs::symlink_metadata(p).is_ok()
}

pub fn canonicalize(p: &str) -> String {
    std::fs::canonicalize(p)
        .map(|p| p.to_string_lossy().to_string())
        .unwrap_or_else(|_| absolutize(p))
}
