//! A pragmatic YAML 1.2 parser that mimics libyaml's scanner/parser behaviour and
//! error messages closely enough for the message parsing paths.

use std::fmt;

/// 0-based line/column position.
#[derive(Debug, Clone, Copy, PartialEq, Default)]
pub struct Pos {
    pub line: usize,
    pub col: usize,
}

impl Pos {
    pub fn line1(&self) -> usize {
        self.line + 1
    }
    pub fn col1(&self) -> usize {
        self.col + 1
    }
}

#[derive(Debug, Clone, PartialEq)]
pub enum ScalarStyle {
    Plain,
    SingleQuoted,
    DoubleQuoted,
    Literal,
    Folded,
}

#[derive(Debug, Clone, PartialEq)]
pub enum Resolved {
    Null,
    Bool(bool),
    Int(i64),
    UInt(u64),
    /// Integer that does not fit into i64/u64.
    Big { raw: String, signed: bool },
    Float(f64),
    Str,
}

/// A parsed YAML node together with the position where its token starts.
#[derive(Debug, Clone, PartialEq)]
pub struct Node {
    pub kind: Kind,
    pub pos: Pos,
}

#[derive(Debug, Clone, PartialEq)]
pub enum Kind {
    Scalar {
        raw: String,
        resolved: Resolved,
        style: ScalarStyle,
    },
    Seq(Vec<Node>),
    Map(Vec<(String, Node)>),
}

impl Node {
    pub fn scalar(raw: String, resolved: Resolved, style: ScalarStyle, pos: Pos) -> Node {
        Node {
            kind: Kind::Scalar { raw, resolved, style },
            pos,
        }
    }
    pub fn null(pos: Pos) -> Node {
        Node::scalar(String::new(), Resolved::Null, ScalarStyle::Plain, pos)
    }
    pub fn seq(items: Vec<Node>, pos: Pos) -> Node {
        Node { kind: Kind::Seq(items), pos }
    }
    pub fn map(items: Vec<(String, Node)>, pos: Pos) -> Node {
        Node { kind: Kind::Map(items), pos }
    }
    pub fn raw(&self) -> &str {
        match &self.kind {
            Kind::Scalar { raw, .. } => raw,
            _ => "",
        }
    }
    pub fn items(&self) -> Option<&[(String, Node)]> {
        match &self.kind {
            Kind::Map(v) => Some(v),
            _ => None,
        }
    }
    pub fn elems(&self) -> Option<&[Node]> {
        match &self.kind {
            Kind::Seq(v) => Some(v),
            _ => None,
        }
    }
}

#[derive(Debug, Clone)]
pub struct Error {
    pub message: String,
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.message)
    }
}

pub type Result<T> = std::result::Result<T, Error>;

const SINGLE_QUOTE: char = '\'';

struct Ctx {
    chars: Vec<char>,
    idx: usize,
}

impl Ctx {
    fn line_col(&self, idx: usize) -> (usize, usize) {
        let mut line = 0;
        let mut col = 0;
        for c in self.chars.iter().take(idx) {
            if *c == '\n' {
                line += 1;
                col = 0;
            } else {
                col += 1;
            }
        }
        (line, col)
    }
    fn pos(&self, idx: usize) -> Pos {
        let (line, col) = self.line_col(idx);
        Pos { line, col }
    }
    fn at(&self, idx: usize) -> Option<char> {
        self.chars.get(idx).copied()
    }
    fn cur(&self) -> Option<char> {
        self.at(self.idx)
    }
    fn peek(&self, n: usize) -> Option<char> {
        self.at(self.idx + n)
    }
    fn at_end(&self) -> bool {
        self.idx >= self.chars.len()
    }
    fn bump(&mut self) -> Option<char> {
        let c = self.cur();
        if c.is_some() {
            self.idx += 1;
        }
        c
    }
}

fn is_space(c: char) -> bool {
    c == ' '
}
fn is_break(c: char) -> bool {
    c == '\n' || c == '\r'
}
fn is_blank(c: char) -> bool {
    c == ' ' || is_break(c)
}

pub struct Parser {
    s: Ctx,
    anchors: Vec<(String, Node)>,
    /// nesting depth (libyaml's default limit is 128)
    depth: usize,
}

impl Parser {
    pub fn new(input: &str) -> Parser {
        Parser {
            s: Ctx {
                chars: input.chars().collect(),
                idx: 0,
            },
            anchors: Vec::new(),
            depth: 0,
        }
    }

    fn err<T>(&self, pos: Pos, problem: &str, context: Option<(&str, Pos)>) -> Result<T> {
        let mut msg = format!(
            "{} at line {} column {}",
            problem,
            pos.line1(),
            pos.col1()
        );
        if let Some((ctx, cpos)) = context {
            msg += &format!(", {} at line {} column {}", ctx, cpos.line1(), cpos.col1());
        }
        Err(Error { message: msg })
    }

    fn starts_with(&self, pat: &str) -> bool {
        for (i, c) in pat.chars().enumerate() {
            if self.s.peek(i) != Some(c) {
                return false;
            }
        }
        true
    }

    fn read_while<F: Fn(char) -> bool>(&mut self, f: F) -> String {
        let mut out = String::new();
        while let Some(c) = self.cur() {
            if f(c) {
                out.push(c);
                self.s.bump();
            } else {
                break;
            }
        }
        out
    }

    /// Skips spaces, breaks and comments.
    fn skip_to_next_token(&mut self) -> bool {
        loop {
            match self.cur() {
                Some(' ') => {
                    self.s.bump();
                }
                Some('\r') | Some('\n') => {
                    self.s.bump();
                }
                Some('#') => {
                    while let Some(c) = self.cur() {
                        if is_break(c) {
                            break;
                        }
                        self.s.bump();
                    }
                }
                _ => return !self.s.at_end(),
            }
        }
    }

    fn skip_inline_spaces(&mut self) {
        while self.cur() == Some(' ') {
            self.s.bump();
        }
    }

    fn skip_breaks(&mut self) -> bool {
        let mut any = false;
        while let Some(c) = self.cur() {
            if is_break(c) {
                self.s.bump();
                any = true;
            } else {
                break;
            }
        }
        any
    }

    fn end_of_line(&mut self) {
        while let Some(c) = self.cur() {
            if is_break(c) {
                break;
            }
            self.s.bump();
        }
    }

    /// Column of the first non-space character of the current line.
    fn line_indent(&self) -> usize {
        let mut i = self.s.idx;
        while i > 0 && self.s.chars[i - 1] != '\n' {
            i -= 1;
        }
        let mut indent = 0;
        while i < self.s.chars.len() {
            match self.s.chars[i] {
                ' ' => {
                    indent += 1;
                    i += 1;
                }
                '\t' => return indent,
                _ => return indent,
            }
        }
        indent
    }

    /// True if the input contains a control character (except \t, \n, \r).
    fn check_control(&self) -> Option<usize> {
        for (i, c) in self.s.chars.iter().enumerate() {
            let u = *c as u32;
            if u < 0x20 && c != '\t' && c != '\n' && c != '\r' {
                return Some(i);
            }
            if u == 0x7f {
                return Some(i);
            }
        }
        None
    }

    pub fn parse_doc(&mut self) -> Result<(Node, bool)> {
        if let Some(i) = self.check_control() {
            let _p = self.s.pos(i);
            return Err(Error {
                message: "control characters are not allowed".to_string(),
            });
        }
        let start = self.s.pos(self.s.idx);
        let node = self.parse_document()?;
        let empty = self.no_content();
        if empty {
            return Ok((Node::null(start), true));
        }
        Ok((node, false))
    }

    fn no_content(&self) -> bool {
        let mut i = 0usize;
        while i < self.s.chars.len() {
            let c = self.s.chars[i];
            if c == '#' {
                while i < self.s.chars.len() && self.s.chars[i] != '\n' {
                    i += 1;
                }
            } else if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
                i += 1;
            } else {
                return false;
            }
        }
        true
    }

    fn parse_document(&mut self) -> Result<Node> {
        let mut docs = 0usize;
        let mut result: Option<Node> = None;
        loop {
            self.skip_to_next_token();
            if self.s.at_end() {
                break;
            }
            if self.cur() == Some('%') {
                // directive
                let dpos = self.s.pos(self.s.idx);
                self.s.bump();
                self.skip_inline_spaces();
                let name_pos = self.s.pos(self.s.idx);
                let name = self.read_while(|c| !is_blank(c));
                if name.is_empty() {
                    return self.err(
                        dpos,
                        "could not find expected directive name",
                        Some(("while scanning a directive", dpos)),
                    );
                }
                if name != "YAML" && name != "TAG" {
                    return self.err(
                        name_pos,
                        "found unknown directive name",
                        Some(("while scanning a directive", dpos)),
                    );
                }
                self.end_of_line();
                continue;
            }
            if self.starts_with("---") {
                self.s.bump();
                self.s.bump();
                self.s.bump();
                docs += 1;
                if docs > 1 {
                    return Err(Error {
                        message:
                            "deserializing from YAML containing more than one document is not supported"
                                .to_string(),
                    });
                }
                continue;
            }
            if self.starts_with("...") {
                for _ in 0..3 {
                    self.s.bump();
                }
                continue;
            }
            let node = self.parse_node(false, 0)?;
            result = Some(node);
            docs += 1;
            if docs > 1 {
                return Err(Error {
                    message:
                        "deserializing from YAML containing more than one document is not supported"
                            .to_string(),
                });
            }
            // after a document, only document end markers / comments may follow
            self.skip_to_next_token();
            if !self.s.at_end() && !self.starts_with("---") && !self.starts_with("...") {
                let p = self.s.pos(self.s.idx);
                return self.err(
                    p,
                    "found character that cannot start any token",
                    Some(("while scanning for the next token", p)),
                );
            }
        }
        if result.is_none() {
            return Err(Error {
                message: "did not find expected node content, while parsing a block node"
                    .to_string(),
            });
        }
        Ok(result.unwrap())
    }

    /// Parses a node in block or flow context. `min_indent` is the minimum
    /// indentation for block content belonging to this node.
    fn parse_node(&mut self, flow: bool, min_indent: usize) -> Result<Node> {
        if flow {
            return self.parse_flow_node();
        }
        self.skip_to_next_token();
        let pos = self.s.pos(self.s.idx);
        if self.s.at_end() {
            return Ok(Node::null(pos));
        }
        // anchors and tags
        let mut anchor: Option<String> = None;
        let mut tag: Option<String> = None;
        loop {
            match self.cur() {
                Some('&') => {
                    self.s.bump();
                    let name = self.read_while(|c| !is_blank(c) && c != ',' && c != ']' && c != '}');
                    anchor = Some(name);
                    self.skip_to_next_token();
                }
                Some('!') => {
                    let t = self.read_tag();
                    tag = Some(t);
                    self.skip_to_next_token();
                }
                _ => break,
            }
        }
        let indent = self.line_indent();
        if indent < min_indent {
            return Ok(Node::null(pos));
        }
        let node = match self.cur() {
            Some('*') => {
                let apos = self.s.pos(self.s.idx);
                self.s.bump();
                let name = self.read_while(|c| !is_blank(c) && c != ',' && c != ']' && c != '}');
                match self.anchors.iter().find(|(a, _)| a == &name) {
                    Some((_, n)) => n.clone(),
                    None => {
                        return self.err(apos, "unknown anchor", None);
                    }
                }
            }
            Some('[') => self.parse_flow_seq()?,
            Some('{') => self.parse_flow_map()?,
            Some('|') | Some('>') => self.parse_block_scalar(indent)?,
            Some('-') if self.is_block_seq_entry() => self.parse_block_seq(indent, min_indent)?,
            _ => {
                if self.is_block_map_entry() {
                    self.parse_block_map(indent, min_indent)?
                } else {
                    self.parse_scalar(indent, false)?
                }
            }
        };
        if let Some(name) = anchor {
            self.anchors.push((name, node.clone()));
        }
        let node = match tag {
            Some(t) => apply_tag(t, node),
            None => node,
        };
        Ok(node)
    }

    fn read_tag(&mut self) -> String {
        let mut out = String::new();
        if self.cur() == Some('!') {
            out.push('!');
            self.s.bump();
        }
        if self.cur() == Some('<') {
            self.s.bump();
            out.push('<');
            out.push_str(&self.read_while(|c| c != '>'));
            if self.cur() == Some('>') {
                out.push('>');
                self.s.bump();
            }
            return out;
        }
        out.push_str(&self.read_while(|c| !is_blank(c) && c != ',' && c != ']' && c != '}'));
        out
    }

    fn is_block_seq_entry(&self) -> bool {
        if self.cur() != Some('-') {
            return false;
        }
        match self.s.peek(1) {
            None => true,
            Some(c) => is_blank(c),
        }
    }

    /// Looks for a `:` that terminates a block mapping key on the current line.
    fn is_block_map_entry(&self) -> bool {
        let mut i = self.s.idx;
        let mut depth = 0i32;
        let mut quote: Option<char> = None;
        while i < self.s.chars.len() {
            let c = self.s.chars[i];
            if let Some(q) = quote {
                if c == q {
                    if q == SINGLE_QUOTE && self.s.chars.get(i + 1) == Some(&SINGLE_QUOTE) {
                        i += 2;
                        continue;
                    }
                    quote = None;
                } else if is_break(c) {
                    return false;
                }
                i += 1;
                continue;
            }
            match c {
                '"' | '\'' => quote = Some(c),
                '[' | '{' => depth += 1,
                ']' | '}' => depth -= 1,
                '#' if i > self.s.idx && self.s.chars[i - 1] == ' ' => return false,
                ':' if depth == 0 => {
                    return match self.s.chars.get(i + 1) {
                        None => true,
                        Some(n) => is_blank(*n),
                    }
                }
                '\n' | '\r' => return false,
                _ => {}
            }
            i += 1;
        }
        false
    }

    fn parse_flow_seq(&mut self) -> Result<Node> {
        let seq_pos = self.s.pos(self.s.idx);
        self.s.bump();
        let mut items = Vec::new();
        loop {
            self.skip_to_next_token();
            match self.cur() {
                Some(']') => {
                    self.s.bump();
                    break;
                }
                None => {
                    let p = self.s.pos(self.s.idx);
                    return self.err(
                        p,
                        "did not find expected node content",
                        Some(("while parsing a flow node", p)),
                    );
                }
                _ => {}
            }
            if self.cur() == Some(',') {
                let p = self.s.pos(self.s.idx);
                items.push(Node::null(p));
                self.s.bump();
                continue;
            }
            let node = self.parse_node(true, 0)?;
            items.push(node);
            self.skip_to_next_token();
            match self.cur() {
                Some(',') => {
                    self.s.bump();
                }
                Some(']') => {
                    self.s.bump();
                    break;
                }
                _ => {
                    let p = self.s.pos(self.s.idx);
                    return self.err(
                        p,
                        "did not find expected ',' or ']'",
                        Some(("while parsing a flow sequence", seq_pos)),
                    );
                }
            }
        }
        Ok(Node::seq(items, seq_pos))
    }

    fn parse_flow_map(&mut self) -> Result<Node> {
        let map_pos = self.s.pos(self.s.idx);
        self.s.bump();
        let mut items: Vec<(String, Node)> = Vec::new();
        loop {
            self.skip_to_next_token();
            match self.cur() {
                Some('}') => {
                    self.s.bump();
                    break;
                }
                None => {
                    let p = self.s.pos(self.s.idx);
                    return self.err(
                        p,
                        "did not find expected node content",
                        Some(("while parsing a flow node", p)),
                    );
                }
                _ => {}
            }
            let key_node = self.parse_flow_node()?;
            let key = key_string(&key_node);
            self.skip_to_next_token();
            let value = if self.cur() == Some(':') {
                self.s.bump();
                self.skip_to_next_token();
                match self.cur() {
                    Some(',') | Some('}') | None => Node::null(self.s.pos(self.s.idx)),
                    _ => self.parse_node(true, 0)?,
                }
            } else {
                Node::null(self.s.pos(self.s.idx))
            };
            if items.iter().any(|(k, _)| k == &key) {
                let p = self.s.pos(self.s.idx);
                return Err(Error {
                    message: format!("duplicate entry with key {:?}", key),
                }
                .with_pos(p));
            }
            items.push((key, value));
            self.skip_to_next_token();
            match self.cur() {
                Some(',') => {
                    self.s.bump();
                }
                Some('}') => {
                    self.s.bump();
                    break;
                }
                _ => {
                    let p = self.s.pos(self.s.idx);
                    return self.err(
                        p,
                        "did not find expected ',' or '}'",
                        Some(("while parsing a flow mapping", map_pos)),
                    );
                }
            }
        }
        Ok(Node::map(items, map_pos))
    }

    fn parse_flow_node(&mut self) -> Result<Node> {
        self.skip_to_next_token();
        let pos = self.s.pos(self.s.idx);
        let mut anchor: Option<String> = None;
        let mut tag: Option<String> = None;
        loop {
            match self.cur() {
                Some('&') => {
                    self.s.bump();
                    let name = self.read_while(|c| !is_blank(c) && c != ',' && c != ']' && c != '}');
                    anchor = Some(name);
                    self.skip_to_next_token();
                }
                Some('!') => {
                    let t = self.read_tag();
                    tag = Some(t);
                    self.skip_to_next_token();
                }
                _ => break,
            }
        }
        let node = match self.cur() {
            Some('*') => {
                let apos = self.s.pos(self.s.idx);
                self.s.bump();
                let name = self.read_while(|c| !is_blank(c) && c != ',' && c != ']' && c != '}');
                match self.anchors.iter().find(|(a, _)| a == &name) {
                    Some((_, n)) => n.clone(),
                    None => return self.err(apos, "unknown anchor", None),
                }
            }
            Some('[') => self.parse_flow_seq()?,
            Some('{') => self.parse_flow_map()?,
            Some('"') => {
                let s = self.parse_double_quoted()?;
                Node::scalar(s, Resolved::Str, ScalarStyle::DoubleQuoted, pos)
            }
            Some('\'') => {
                let s = self.parse_single_quoted()?;
                Node::scalar(s, Resolved::Str, ScalarStyle::SingleQuoted, pos)
            }
            _ => {
                let (raw, style) = self.parse_plain(true)?;
                let resolved = resolve_plain(&raw);
                Node::scalar(raw, resolved, style, pos)
            }
        };
        if let Some(name) = anchor {
            self.anchors.push((name, node.clone()));
        }
        Ok(match tag {
            Some(t) => apply_tag(t, node),
            None => node,
        })
    }

    fn parse_block_seq(&mut self, indent: usize, _min_indent: usize) -> Result<Node> {
        let seq_pos = self.s.pos(self.s.idx);
        let mut items = Vec::new();
        loop {
            self.skip_to_next_token();
            if self.s.at_end() {
                break;
            }
            if self.line_indent() != indent || !self.is_block_seq_entry() {
                break;
            }
            self.s.bump(); // '-'
            self.skip_inline_spaces();
            let content_col = self.col_of_idx();
            if self.s.at_end() || is_break(self.cur().unwrap()) || self.cur() == Some('#') {
                // value on following lines
                self.end_of_line();
                let node = self.parse_block_value(indent, content_col)?;
                items.push(node);
            } else {
                let node = self.parse_node(false, content_col)?;
                items.push(node);
            }
        }
        Ok(Node::seq(items, seq_pos))
    }

    fn col_of_idx(&self) -> usize {
        self.s.pos(self.s.idx).col
    }

    /// Parses the value of a `-` entry or mapping key that starts on the next line.
    fn parse_block_value(&mut self, parent_indent: usize, min_indent: usize) -> Result<Node> {
        self.skip_to_next_token();
        if self.s.at_end() {
            let p = self.s.pos(self.s.idx);
            return Ok(Node::null(p));
        }
        let ind = self.line_indent();
        if ind < min_indent {
            let p = self.s.pos(self.s.idx);
            return Ok(Node::null(p));
        }
        self.parse_node(false, min_indent)
    }

    fn parse_block_map(&mut self, indent: usize, _min_indent: usize) -> Result<Node> {
        let map_pos = self.s.pos(self.s.idx);
        let mut items: Vec<(String, Node)> = Vec::new();
        loop {
            self.skip_to_next_token();
            if self.s.at_end() {
                break;
            }
            let li = self.line_indent();
            if li < indent {
                break;
            }
            if li > indent {
                let p = self.s.pos(self.s.idx);
                return self.err(
                    p,
                    "mapping values are not allowed in this context",
                    None,
                );
            }
            if !self.is_block_map_entry() {
                break;
            }
            let key_node = self.parse_key()?;
            self.skip_inline_spaces();
            if self.cur() != Some(':') {
                let p = self.s.pos(self.s.idx);
                return self.err(
                    p,
                    "could not find expected ':'",
                    Some(("while scanning a simple key", map_pos)),
                );
            }
            self.s.bump();
            self.skip_inline_spaces();
            let value = if self.s.at_end() || is_break(self.cur().unwrap()) {
                self.end_of_line();
                self.parse_block_map_value(indent)?
            } else if self.cur() == Some('#') {
                self.end_of_line();
                self.parse_block_map_value(indent)?
            } else {
                let vpos = self.s.pos(self.s.idx);
                match self.cur() {
                    Some('|') | Some('>') => self.parse_block_scalar(indent)?,
                    Some('"') => {
                        let s = self.parse_double_quoted()?;
                        self.check_mapping_value(vpos)?;
                        Node::scalar(s, Resolved::Str, ScalarStyle::DoubleQuoted, vpos)
                    }
                    Some('\'') => {
                        let s = self.parse_single_quoted()?;
                        self.check_mapping_value(vpos)?;
                        Node::scalar(s, Resolved::Str, ScalarStyle::SingleQuoted, vpos)
                    }
                    Some('[') => self.parse_flow_seq()?,
                    Some('{') => self.parse_flow_map()?,
                    _ => {
                        let (raw, style) = self.parse_plain(false)?;
                        self.check_mapping_value(vpos)?;
                        let resolved = resolve_plain(&raw);
                        Node::scalar(raw, resolved, style, vpos)
                    }
                }
            };
            if items.iter().any(|(k, _)| k == &key_node.0) {
                return Err(Error {
                    message: format!("duplicate entry with key {:?}", key_node.0),
                }
                .with_pos(key_node.1 .1));
            }
            items.push((key_node.0, value));
        }
        Ok(Node::map(items, map_pos))
    }

    /// After reading a plain value on the same line, a following `:` is invalid.
    fn check_mapping_value(&self, vpos: Pos) -> Result<()> {
        if self.cur() == Some(':') {
            return self.err(vpos, "mapping values are not allowed in this context", None);
        }
        Ok(())
    }

    /// The value of a mapping key found on the following lines.
    fn parse_block_map_value(&mut self, key_indent: usize) -> Result<Node> {
        self.skip_to_next_token();
        if self.s.at_end() {
            let p = self.s.pos(self.s.idx);
            return Ok(Node::null(p));
        }
        let ind = self.line_indent();
        if ind <= key_indent {
            // a sequence may be at the same indentation as its parent key
            if ind == key_indent && self.is_block_seq_entry() {
                return self.parse_block_seq(ind, 0);
            }
            let p = self.s.pos(self.s.idx);
            return Ok(Node::null(p));
        }
        self.parse_node(false, ind)
    }

    fn parse_key(&mut self) -> Result<(String, Pos)> {
        let pos = self.s.pos(self.s.idx);
        match self.cur() {
            Some('"') => {
                let s = self.parse_double_quoted()?;
                Ok((s, pos))
            }
            Some('\'') => {
                let s = self.parse_single_quoted()?;
                Ok((s, pos))
            }
            Some('[') => {
                let n = self.parse_flow_seq()?;
                Ok((key_string(&n), pos))
            }
            Some('{') => {
                let n = self.parse_flow_map()?;
                Ok((key_string(&n), pos))
            }
            _ => {
                let s = self.read_plain_key()?;
                Ok((s, pos))
            }
        }
    }

    fn read_plain_key(&mut self) -> Result<String> {
        let mut out = String::new();
        loop {
            match self.cur() {
                None | Some('\n') | Some('\r') => break,
                Some(':') => break,
                Some('#') if !out.is_empty() && out.ends_with(' ') => break,
                Some(c) => {
                    out.push(c);
                    self.s.bump();
                }
            }
        }
        Ok(out.trim_end().to_string())
    }

    fn parse_scalar(&mut self, indent: usize, flow: bool) -> Result<Node> {
        let pos = self.s.pos(self.s.idx);
        match self.cur() {
            Some('"') => {
                let s = self.parse_double_quoted()?;
                Ok(Node::scalar(s, Resolved::Str, ScalarStyle::DoubleQuoted, pos))
            }
            Some('\'') => {
                let s = self.parse_single_quoted()?;
                Ok(Node::scalar(s, Resolved::Str, ScalarStyle::SingleQuoted, pos))
            }
            _ => {
                let start = pos;
                let (raw, style) = self.parse_plain(flow)?;
                if let Some(c) = self.cur() {
                    if !is_blank(c) && c != ',' && c != ']' && c != '}' && c != ':' {
                        return self.err(
                            start,
                            "found character that cannot start any token",
                            Some(("while scanning for the next token", start)),
                        );
                    }
                }
                let resolved = resolve_plain(&raw);
                Ok(Node::scalar(raw, resolved, style, start))
            }
        }
    }

    fn parse_plain(&mut self, flow: bool) -> Result<(String, ScalarStyle)> {
        let mut lines: Vec<String> = Vec::new();
        let mut cur = String::new();
        let mut stopped = false;
        loop {
            match self.cur() {
                None => break,
                Some(c) if is_break(c) => {
                    self.s.bump();
                    break;
                }
                Some(',') | Some(']') | Some('}') | Some(':') if flow => {
                    stopped = true;
                    break;
                }
                Some('#') if !cur.is_empty() && cur.ends_with(' ') => {
                    self.end_of_line();
                    break;
                }
                Some(c) => {
                    cur.push(c);
                    self.s.bump();
                }
            }
        }
        if cur.is_empty() && stopped {
            // nothing consumed
        }
        lines.push(cur.trim_end().to_string());
        if !stopped {
            // multi-line plain scalars
            loop {
                let save = self.s.idx;
                let mut blanks = 0usize;
                let mut i = self.s.idx;
                let mut ind = 0usize;
                let mut saw_content = false;
                while i < self.s.chars.len() {
                    match self.s.chars[i] {
                        ' ' => {
                            ind += 1;
                            i += 1;
                        }
                        '\t' => {
                            ind += 1;
                            i += 1;
                        }
                        '\r' | '\n' => {
                            blanks += 1;
                            ind = 0;
                            i += 1;
                        }
                        _ => {
                            saw_content = true;
                            break;
                        }
                    }
                }
                if !saw_content {
                    self.s.idx = i;
                    break;
                }
                // content must be indented more than the first line
                if ind == 0 {
                    self.s.idx = save;
                    break;
                }
                let mut line = String::new();
                let mut j = i;
                while j < self.s.chars.len() {
                    let c = self.s.chars[j];
                    if c == '#' && line.ends_with(' ') {
                        break;
                    }
                    if is_break(c) {
                        break;
                    }
                    if c == ':' && line.contains(' ') {
                        // a mapping value is not allowed here
                        break;
                    }
                    line.push(c);
                    j += 1;
                }
                let trimmed = line.trim_end().to_string();
                if trimmed.is_empty() {
                    self.s.idx = save;
                    break;
                }
                self.s.idx = j;
                for _ in 0..blanks {
                    lines.push(String::new());
                }
                lines.push(trimmed);
            }
        }
        Ok((fold_lines(&lines), ScalarStyle::Plain))
    }

    fn parse_single_quoted(&mut self) -> Result<String> {
        let start = self.s.pos(self.s.idx);
        self.s.bump();
        let mut lines: Vec<String> = Vec::new();
        let mut cur = String::new();
        loop {
            match self.cur() {
                None => {
                    return self.err(
                        start,
                        "found unexpected end of stream",
                        Some(("while scanning a quoted scalar", start)),
                    )
                }
                Some('\'') => {
                    if self.s.peek(1) == Some('\'') {
                        cur.push('\'');
                        self.s.bump();
                        self.s.bump();
                    } else {
                        self.s.bump();
                        break;
                    }
                }
                Some(c) if is_break(c) => {
                    self.s.bump();
                    lines.push(std::mem::take(&mut cur));
                    while self.cur() == Some(' ') {
                        self.s.bump();
                    }
                    // leading blank lines are preserved as empty lines
                    if self.skip_breaks() {
                        lines.push(String::new());
                    }
                }
                Some(c) => {
                    cur.push(c);
                    self.s.bump();
                }
            }
        }
        lines.push(std::mem::take(&mut cur));
        Ok(fold_lines(&lines).trim_end().to_string())
    }

    fn parse_double_quoted(&mut self) -> Result<String> {
        let start = self.s.pos(self.s.idx);
        self.s.bump();
        let mut lines: Vec<String> = Vec::new();
        let mut cur = String::new();
        loop {
            match self.cur() {
                None => {
                    return self.err(
                        start,
                        "found unexpected end of stream",
                        Some(("while scanning a quoted scalar", start)),
                    )
                }
                Some('"') => {
                    self.s.bump();
                    break;
                }
                Some('\\') => {
                    self.s.bump();
                    match self.cur() {
                        None => {
                            return self.err(
                                start,
                                "found unknown escape character",
                                Some(("while parsing a quoted scalar", start)),
                            )
                        }
                        Some(ch) => {
                            match ch {
                                '0' => cur.push('\0'),
                                'a' => cur.push('\u{7}'),
                                'b' => cur.push('\u{8}'),
                                't' => cur.push('\t'),
                                '\t' => cur.push('\t'),
                                'n' => cur.push('\n'),
                                'v' => cur.push('\u{b}'),
                                'f' => cur.push('\u{c}'),
                                'r' => cur.push('\r'),
                                'e' => cur.push('\u{1b}'),
                                ' ' => cur.push(' '),
                                '"' => cur.push('"'),
                                '/' => cur.push('/'),
                                '\\' => cur.push('\\'),
                                'N' => cur.push('\u{85}'),
                                '_' => cur.push('\u{a0}'),
                                'L' => cur.push('\u{2028}'),
                                'P' => cur.push('\u{2029}'),
                                'x' | 'u' | 'U' => {
                                    self.s.bump();
                                    let n = match ch {
                                        'x' => 2,
                                        'u' => 4,
                                        _ => 8,
                                    };
                                    let mut v: u32 = 0;
                                    for _ in 0..n {
                                        match self.cur() {
                                            Some(d) if d.is_ascii_hexdigit() => {
                                                v = v * 16 + d.to_digit(16).unwrap();
                                                self.s.bump();
                                            }
                                            _ => {
                                                let p = self.s.pos(self.s.idx);
                                                return self.err(
                                                    p,
                                                    "did not find expected hexdecimal number",
                                                    Some(("while parsing a quoted scalar", start)),
                                                );
                                            }
                                        }
                                    }
                                    match char::from_u32(v) {
                                        Some(c) => cur.push(c),
                                        None => {
                                            let p = self.s.pos(self.s.idx);
                                            return self.err(
                                                p,
                                                "found invalid Unicode character escape code",
                                                Some(("while parsing a quoted scalar", start)),
                                            );
                                        }
                                    }
                                    continue;
                                }
                                c if is_break(c) => {
                                    self.s.bump();
                                    while self.cur() == Some(' ') {
                                        self.s.bump();
                                    }
                                    continue;
                                }
                                _ => {
                                    let p = self.s.pos(self.s.idx);
                                    return self.err(
                                        p,
                                        "found unknown escape character",
                                        Some(("while parsing a quoted scalar", start)),
                                    );
                                }
                            }
                            self.s.bump();
                        }
                    }
                }
                Some(c) if is_break(c) => {
                    self.s.bump();
                    lines.push(std::mem::take(&mut cur));
                    while self.cur() == Some(' ') {
                        self.s.bump();
                    }
                    if self.skip_breaks() {
                        lines.push(String::new());
                    }
                }
                Some(c) => {
                    cur.push(c);
                    self.s.bump();
                }
            }
        }
        lines.push(std::mem::take(&mut cur));
        Ok(fold_lines(&lines).trim_end().to_string())
    }

    fn parse_block_scalar(&mut self, indent: usize) -> Result<Node> {
        let start = self.s.pos(self.s.idx);
        let style = if self.cur() == Some('|') {
            ScalarStyle::Literal
        } else {
            ScalarStyle::Folded
        };
        self.s.bump();
        let mut chomp = ' ';
        let mut explicit: Option<usize> = None;
        loop {
            match self.cur() {
                Some('-') | Some('+') => {
                    chomp = self.cur().unwrap();
                    self.s.bump();
                }
                Some('0'..='9') => {
                    explicit = Some(self.cur().unwrap().to_digit(10).unwrap() as usize);
                    self.s.bump();
                }
                _ => break,
            }
        }
        self.end_of_line();
        let mut lines: Vec<String> = Vec::new();
        let mut base: Option<usize> = explicit;
        loop {
            if self.s.at_end() {
                break;
            }
            let mut i = self.s.idx;
            let mut ind = 0usize;
            let mut only_space = true;
            while i < self.s.chars.len() {
                match self.s.chars[i] {
                    ' ' | '\t' => {
                        ind += 1;
                        i += 1;
                    }
                    '\n' => break,
                    _ => {
                        only_space = false;
                        break;
                    }
                }
            }
            if only_space {
                if i >= self.s.chars.len() {
                    self.s.idx = i;
                    break;
                }
                // blank line inside the block scalar
                let save = self.s.idx;
                self.s.idx = i + 1;
                // determine whether the block continues
                let mut j = self.s.idx;
                let mut ind2 = 0usize;
                while j < self.s.chars.len() && self.s.chars[j] == ' ' {
                    ind2 += 1;
                    j += 1;
                }
                if j >= self.s.chars.len() || ind2 < base.unwrap_or(1) {
                    self.s.idx = save;
                    break;
                }
                lines.push(String::new());
                continue;
            }
            if base.is_none() {
                if ind <= indent {
                    self.s.idx = i;
                    break;
                }
                base = Some(ind);
            }
            let b = base.unwrap();
            if ind < b {
                self.s.idx = i;
                break;
            }
            self.s.idx = i;
            let mut line = " ".repeat(ind - b);
            while let Some(c) = self.cur() {
                if is_break(c) {
                    break;
                }
                line.push(c);
                self.s.bump();
            }
            if self.cur() == Some('\n') {
                self.s.bump();
            }
            lines.push(line);
        }
        let out = match style {
            ScalarStyle::Literal => {
                let mut o: String = lines.iter().map(|l| format!("{}\n", l)).collect();
                if chomp == '-' {
                    while o.ends_with('\n') {
                        o.pop();
                    }
                } else if chomp == ' ' {
                    while o.ends_with("\n\n") {
                        o.pop();
                    }
                }
                o
            }
            _ => {
                let mut o = String::new();
                let mut first = true;
                let mut prev_more = false;
                for l in &lines {
                    if first {
                        o.push_str(l);
                        first = false;
                        continue;
                    }
                    if l.starts_with(' ') || prev_more {
                        o.push('\n');
                        o.push_str(l);
                    } else if l.is_empty() {
                        o.push('\n');
                    } else {
                        o.push(' ');
                        o.push_str(l);
                    }
                    prev_more = l.starts_with(' ');
                }
                if chomp == '+' {
                    o.push('\n');
                }
                o
            }
        };
        Ok(Node::scalar(out, Resolved::Str, style, start))
    }
}

impl Error {
    fn with_pos(mut self, pos: Pos) -> Error {
        self.message = format!(
            "{} at line {} column {}",
            self.message,
            pos.line1(),
            pos.col1()
        );
        self
    }
}

fn fold_lines(lines: &[String]) -> String {
    let mut out = String::new();
    for (i, l) in lines.iter().enumerate() {
        if i == 0 {
            out.push_str(l);
        } else if l.is_empty() {
            out.push('\n');
        } else {
            if !out.ends_with('\n') {
                out.push(' ');
            }
            out.push_str(l);
        }
    }
    out
}

fn key_string(node: &Node) -> String {
    match &node.kind {
        Kind::Scalar { raw, .. } => raw.clone(),
        Kind::Seq(v) => format!("{:?}", v.len()),
        Kind::Map(v) => format!("{:?}", v.len()),
    }
}

fn apply_tag(tag: String, node: Node) -> Node {
    let pos = node.pos;
    match tag.as_str() {
        "!!str" | "!str" => match node.kind {
            Kind::Scalar { raw, style, .. } => Node::scalar(raw, Resolved::Str, style, pos),
            _ => node,
        },
        "!!int" | "!int" => match node.kind {
            Kind::Scalar { raw, style, .. } => Node::scalar(
                raw.clone(),
                parse_int(&raw).unwrap_or(Resolved::Str),
                style,
                pos,
            ),
            _ => node,
        },
        "!!float" | "!float" => match node.kind {
            Kind::Scalar { raw, style, .. } => Node::scalar(
                raw.clone(),
                parse_float(&raw).unwrap_or(Resolved::Str),
                style,
                pos,
            ),
            _ => node,
        },
        "!!bool" | "!bool" => match node.kind {
            Kind::Scalar { raw, style, .. } => Node::scalar(
                raw.clone(),
                parse_bool(&raw).unwrap_or(Resolved::Str),
                style,
                pos,
            ),
            _ => node,
        },
        "!!null" | "!null" => match node.kind {
            Kind::Scalar { raw, style, .. } => Node::scalar(raw, Resolved::Null, style, pos),
            _ => node,
        },
        _ => node,
    }
}

pub fn resolve_plain(raw: &str) -> Resolved {
    if raw.is_empty() {
        return Resolved::Null;
    }
    match raw {
        "~" | "null" | "Null" | "NULL" => return Resolved::Null,
        "true" | "True" | "TRUE" => return Resolved::Bool(true),
        "false" | "False" | "FALSE" => return Resolved::Bool(false),
        _ => {}
    }
    if let Some(r) = parse_int(raw) {
        return r;
    }
    if let Some(r) = parse_float(raw) {
        return r;
    }
    Resolved::Str
}

fn parse_bool(raw: &str) -> Option<Resolved> {
    match raw {
        "true" | "True" | "TRUE" | "y" | "Y" | "yes" | "Yes" | "YES" | "on" | "On" | "ON" => {
            Some(Resolved::Bool(true))
        }
        "false" | "False" | "FALSE" | "n" | "N" | "no" | "No" | "NO" | "off" | "Off" | "OFF" => {
            Some(Resolved::Bool(false))
        }
        _ => None,
    }
}

fn parse_int(raw: &str) -> Option<Resolved> {
    let s = raw.trim();
    if s.is_empty() {
        return None;
    }
    let (neg, body) = if let Some(r) = s.strip_prefix('-') {
        (true, r)
    } else if let Some(r) = s.strip_prefix('+') {
        (false, r)
    } else {
        (false, s)
    };
    let (radix, digits) = if let Some(d) =
        body.strip_prefix("0x").or_else(|| body.strip_prefix("0X"))
    {
        (16u32, d)
    } else if let Some(d) = body.strip_prefix("0o").or_else(|| body.strip_prefix("0O")) {
        (8u32, d)
    } else if let Some(d) = body.strip_prefix("0b").or_else(|| body.strip_prefix("0B")) {
        (2u32, d)
    } else {
        (10u32, body)
    };
    if digits.is_empty() {
        return None;
    }
    if !digits.chars().all(|c| c.is_digit(radix)) {
        return None;
    }
    if radix == 10 && digits.len() > 1 && digits.starts_with('0') {
        return None;
    }
    let v = u64::from_str_radix(digits, radix).ok()?;
    if neg {
        if v <= (i64::MAX as u64) + 1 {
            return Some(Resolved::Int(-(v as i128) as i64));
        }
        return Some(Resolved::Big {
            raw: raw.to_string(),
            signed: true,
        });
    }
    if v <= i64::MAX as u64 {
        Some(Resolved::Int(v as i64))
    } else {
        Some(Resolved::UInt(v))
    }
}

fn parse_float(raw: &str) -> Option<Resolved> {
    let s = raw.trim();
    if s.is_empty() {
        return None;
    }
    let (neg, body) = if let Some(r) = s.strip_prefix('-') {
        (true, r)
    } else if let Some(r) = s.strip_prefix('+') {
        (false, r)
    } else {
        (false, s)
    };
    match body {
        ".inf" | ".Inf" | ".INF" => {
            return Some(Resolved::Float(if neg {
                f64::NEG_INFINITY
            } else {
                f64::INFINITY
            }))
        }
        ".nan" | ".NaN" | ".NAN" => return Some(Resolved::Float(f64::NAN)),
        _ => {}
    }
    if !s.chars().any(|c| c == '.' || c == 'e' || c == 'E') {
        return None;
    }
    let v: f64 = s.parse().ok()?;
    if !v.is_finite() {
        return None;
    }
    Some(Resolved::Float(v))
}
