        let start = self.s.pos(self.s.idx);
        let style = if self.cur() == Some('|') {
            ScalarStyle::Literal
        } else {
            ScalarStyle::Folded
        };
        self.s.bump();
        let mut chomp = ' ';
        let mut explicit: Option<usize> = None;
        loop {
            match self.cur() {
                Some('-') | Some('+') => {
                    chomp = self.cur().unwrap();
                    self.s.bump();
                }
                Some('0'..='9') => {
                    explicit = Some(self.cur().unwrap().to_digit(10).unwrap() as usize);
                    self.s.bump();
                }
                _ => break,
            }
        }
        match self.cur() {
            None | Some('\\n') | Some('\\r') | Some(' ') => {}
            Some(_) => {
                return self.err(
