            while let Some(c) = self.cur() {
                if is_break(c) {
                    break;
                }
                line.push(c);
                self.s.bump();
            }
            let has_break = self.cur().is_some();
            if has_break {
                self.end_of_line();
            }
            ended_with_break = has_break;
            lines.push((line, has_break));
        }
        let mut raw: Vec<String> = Vec::new();
        let mut breaks: Vec<bool> = Vec::new();
        for (l, b) in &lines {
            raw.push(l.clone());
            breaks.push(*b);
        }
        let out = match style {
            ScalarStyle::Literal => {
                let mut o = String::new();
                for (idx, l) in raw.iter().enumerate() {
                    o.push_str(l);
                    if breaks[idx] {
                        o.push('\\n');
                    }
                }
                match chomp {
                    '-' => {
                        while o.ends_with('\\n') {
                            o.pop();
                        }
                        o
                    }
                    '+' => o,
                    _ => {
                        while o.ends_with('\\n') {
                            o.pop();
                        }
                        if ended_with_break {
                            o.push('\\n');
                        }
                        o
                    }
                }
            }
            _ => {
                let mut o = String::new();
                let mut first = true;
                let mut prev_more = false;
                for (idx, l) in raw.iter().enumerate() {
                    if first {
                        o.push_str(l);
                        first = false;
                        prev_more = l.starts_with(' ');
                        continue;
                    }
                    if l.is_empty() {
                        o.push('\\n');
                    } else if l.starts_with(' ') || prev_more {
                        o.push('\\n');
                        o.push_str(l);
                    } else {
                        o.push(' ');
                        o.push_str(l);
                    }
                    prev_more = l.starts_with(' ');
                }
                match chomp {
                    '-' => {
                        while o.ends_with('\\n') {
                            o.pop();
                        }
                        o
                    }
                    '+' => {
                        if ended_with_break {
                            o.push('\\n');
                        }
                        o
                    }
                    _ => {
                        if ended_with_break {
                            o.push('\\n');
                        }
                        o
                    }
                }
            }
        };
        Ok(Node::scalar(out, Resolved::Str, style, start))
    }
}

