//! Converting parsed YAML nodes into a JSON document, mirroring what serde_yaml
//! + serde_json would produce.

use crate::yaml::{Kind, Node, Pos, Resolved};

#[derive(Debug, Clone)]
pub struct YamlError {
    pub path: String,
    pub pos: Option<Pos>,
    pub msg: String,
}

impl std::fmt::Display for YamlError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        if self.path.is_empty() && self.pos.is_none() {
            write!(f, "{}", self.msg)
        } else {
            match &self.pos {
                Some(p) => write!(
                    f,
