"""Minimal YAML parser for the xplr app-state dump (block style only)."""
def parse(text):
    lines = [l for l in text.split('\n')]
    # strip trailing empty lines
    while lines and lines[-1].strip() == '':
        lines.pop()
    pos = [0]
    def peek():
        return lines[pos[0]] if pos[0] < len(lines) else None
    def next_line():
        l = lines[pos[0]]
        pos[0] += 1
        return l
    def indent_of(l):
        n = 0
        while n < len(l) and l[n] == ' ':
            n += 1
        return n
    def parse_block(min_indent):
        # returns value for the block starting at current line
        l = peek()
        if l is None:
            return None
        ind = indent_of(l)
        if ind < min_indent:
            return None
        content = l.strip()
        if content.startswith('- '):
            seq = []
            cur_ind = ind
            while True:
                l = peek()
                if l is None:
                    break
                i = indent_of(l)
                if i < cur_ind or not l.strip().startswith('- '):
                    break
                # gather a sequence item (may be a mapping with more indented keys)
                item_line = l.strip()[2:]
                pos[0] += 1
                if item_line == '':
                    seq.append(parse_block(i + 3))
                    continue
                # item could be "key: value" mapping
                if ':' in item_line and not item_line.startswith('"'):
                    # build a mapping from this and following deeper lines
                    m = {}
                    k, _, v = item_line.partition(':')
                    k = k.strip(); v = v.strip()
                    m[k] = scalar(v)
                    # deeper lines
                    while True:
                        nl = peek()
                        if nl is None:
                            break
                        ni = indent_of(nl)
                        if ni <= i + 1:
                            break
                        sub = nl.strip()
                        pos[0] += 1
                        if sub.startswith('- '):
                            # nested sequence
                            seq2 = [sub[2:].strip()]
                            cur = i + 2
                            while True:
                                l2 = peek()
                                if l2 is None: break
