def style_rust(st, ind):
    pad = ' ' * ind
    fg = st.get('fg')
    bg = st.get('bg')
    add = st.get('add_modifiers')
    sub = st.get('sub_modifiers')
    parts = []
    if fg is not None:
        parts.append('fg: Some(Color::%s)' % fg)
    if bg is not None:
        parts.append('bg: Some(Color::%s)' % bg)
    if add:
        parts.append('add_modifiers: Some(vec![%s])' % ', '.join('Modifier::%s' % m for m in add))
    if sub:
        parts.append('sub_modifiers: Some(vec![%s])' % ', '.join('Modifier::%s' % m for m in sub))
    if not parts:
        return 'Style::default()'
    return 'Style { %s }' % ', '.join(parts)

def ui_config_rust(ui, ind, default_style=True):
    pad = ' ' * ind
    parts = []
    t = ui.get('title')
    if t is None:
        parts.append('title: None')
    else:
        f = t.get('format')
        parts.append('title: Some(TitleConfig { format: %s, style: %s })' % (
            'Some(%s.to_string())' % rs_str(f) if f else 'None', style_rust(t.get('style') or {}, 0)))
    parts.append('style: %s' % style_rust(ui.get('style') or {}, 0))
    b = ui.get('borders')
    if b is None:
        parts.append('borders: None')
    else:
        parts.append('borders: Some(vec![%s])' % ', '.join('Border::%s' % x for x in b))
    bt = ui.get('border_type')
    parts.append('border_type: %s' % ('Some(BorderType::%s)' % bt if bt else 'None'))
    parts.append('border_style: %s' % style_rust(ui.get('border_style') or {}, 0))
    return 'UiConfig { %s }' % ', '.join(parts)

def custom_panel_rust(p, ind):
    if isinstance(p, dict) and len(p) == 1:
        k, v = list(p.items())[0]
        if k == 'CustomParagraph':
            body = v.get('body', '')
            return 'CustomPanel::CustomParagraph { ui: %s, body: %s.to_string() }' % (
                ('Some(%s)' % ui_config_rust(v['ui'], ind)) if v.get('ui') else 'None', rs_str(body))
        if k == 'CustomList':
            body = v.get('body', [])
            return 'CustomPanel::CustomList { ui: %s, body: vec![%s] }' % (
                ('Some(%s)' % ui_config_rust(v['ui'], ind)) if v.get('ui') else 'None',
                ', '.join('%s.to_string()' % rs_str(x) for x in body))
        raise Exception('custom panel %r' % k)
    raise Exception('custom panel %r' % (p,))

def modes_rust():
    out = []
    for name, m in modes.items():
        out.append('        %s: Mode {' % name)
        out.append('            name: %s.to_string(),' % rs_str(m.get('name', name)))
        out.append('            help: %s,' % ('Some(%s.to_string())' % rs_str(m['help']) if m.get('help') else 'None'))
        out.append('            extra_help: %s,' % ('Some(%s.to_string())' % rs_str(m['extra_help']) if m.get('extra_help') else 'None'))
        out.append('            key_bindings: %s,' % keybindings_rust(m['key_bindings'], 12))
        lay = m.get('layout')
        if lay is None:
            out.append('            layout: None,')
        elif isinstance(lay, str) and lay in LAYOUTS:
            out.append('            layout: Some(Layout::builtin(%s)),' % rs_str(lay))
        else:
            out.append('            layout: Some(%s),' % '\n'.join(layout_rust(lay, 12)))
        out.append('            prompt: %s,' % ('Some(%s.to_string())' % rs_str(m['prompt']) if m.get('prompt') else 'None'))
        out.append('        },')
    return '\n'.join(out)

def layouts_rust():
    out = []
    for name, l in LAYOUTS.items():
        out.append('        %s: %s,' % (name, '\n'.join(layout_rust(l, 8))))
    return '\n'.join(out)

if __name__ == '__main__':
    which = sys.argv[1]
    if which == 'modes':
        print(modes_rust())
    elif which == 'layouts':
        print(layouts_rust())
