#[derive(Debug, Clone, PartialEq, Default)]
pub struct NodeTypes {
    pub directory: NodeTypeConfig,
    pub file: NodeTypeConfig,
    pub symlink: NodeTypeConfig,
    pub mime_essence: BTreeMap<String, NodeTypeConfig>,
    pub extension: BTreeMap<String, NodeTypeConfig>,
    pub special: BTreeMap<String, NodeTypeConfig>,
}

impl NodeTypes {
    /// Returns the applicable style and meta for a node.
    pub fn for_node(&self, relative_path: &str, is_dir: bool, is_file: bool, is_symlink: bool, mime: &str) -> (Style, BTreeMap<String, String>) {
        let mut meta: BTreeMap<String, String> = BTreeMap::new();
        let mut style = Style::default();
        let base = if is_symlink {
            &self.symlink
        } else if is_dir {
            &self.directory
        } else if is_file {
            &self.file
        } else {
            &self.file
        };
        style = base.style.clone();
        for (k, v) in base.meta.iter() {
            meta.insert(k.clone(), v.clone());
        }
        if !mime.is_empty() {
            if let Some(nt) = self.mime_essence.get(mime) {
                style = merge_style(style, nt.style.clone());
                for (k, v) in nt.meta.iter() {
                    meta.insert(k.clone(), v.clone());
                }
            }
        }
        let ext = extension_of(relative_path);
        if !ext.is_empty() {
            if let Some(nt) = self.extension.get(&ext) {
                style = merge_style(style, nt.style.clone());
                for (k, v) in nt.meta.iter() {
                    meta.insert(k.clone(), v.clone());
                }
            }
        }
        if let Some(nt) = self.special.get(relative_path) {
            style = merge_style(style, nt.style.clone());
            for (k, v) in nt.meta.iter() {
                meta.insert(k.clone(), v.clone());
            }
        }
        (style, meta)
    }
}

pub fn extension_of(path: &str) -> String {
    let name = path.rsplit('/').next().unwrap_or(path);
    match name.rfind('.') {
        Some(i) if i > 0 => name[i + 1..].to_string(),
        _ => String::new(),
    }
}

fn merge_style(base: Style, other: Style) -> Style {
    Style {
        fg: other.fg.or(base.fg),
        bg: other.bg.or(base.bg),
        add_modifiers: match (base.add_modifiers, other.add_modifiers) {
            (Some(mut a), Some(b)) => {
                a.extend(b);
                Some(a)
            }
            (None, Some(b)) => Some(b),
            (a, None) => a,
        },
        sub_modifiers: match (base.sub_modifiers, other.sub_modifiers) {
            (Some(mut a), Some(b)) => {
                a.extend(b);
                Some(a)
            }
            (None, Some(b)) => Some(b),
            (a, None) => a,
        },
    }
}

