    pub fn for_node(&self, relative_path: &str, is_dir: bool, is_file: bool, is_symlink: bool, mime: &str) -> (Style, BTreeMap<String, String>) {
        let mut meta: BTreeMap<String, String> = BTreeMap::new();
        let mut style = Style::default();
        let base = if is_symlink {
            &self.symlink
        } else if is_dir {
            &self.directory
        } else if is_file {
            &self.file
        } else {
            &self.file
        };
        style = base.style.clone();
        for (k, v) in base.meta.iter() {
            meta.insert(k.clone(), v.clone());
        }
        if !mime.is_empty() {
            if let Some(nt) = self.mime_essence.get(mime) {
                style = merge_style(style, nt.style.clone());
                for (k, v) in nt.meta.iter() {
                    meta.insert(k.clone(), v.clone());
                }
            }
        }
        let ext = extension_of(relative_path);
        if !ext.is_empty() {
            if let Some(nt) = self.extension.get(&ext) {
                style = merge_style(style, nt.style.clone());
                for (k, v) in nt.meta.iter() {
                    meta.insert(k.clone(), v.clone());
                }
            }
        }
        if let Some(nt) = self.special.get(relative_path) {
            style = merge_style(style, nt.style.clone());
            for (k, v) in nt.meta.iter() {
                meta.insert(k.clone(), v.clone());
            }
        }
        (style, meta)
    }
