    pub is_dir: bool,
    pub is_file: bool,
    pub is_symlink: bool,
    pub is_broken: bool,
    pub is_readonly: bool,
    pub mime_essence: String,
    pub size: u64,
    pub human_size: String,
    pub permissions: Permissions,
    pub created: i128,
    pub last_modified: i128,
    pub uid: u32,
    pub gid: u32,
    pub canonical: Option<ResolvedNode>,
    pub symlink: Option<String>,
}

/// Formats a size the way xplr does.
pub fn human_size(size: u64) -> String {
    if size < 1000 {
        format!("{} B", size)
    } else if size < 1000_u64.pow(2) {
        format!("{:.2} kB", size as f64 / 1e3)
    } else if size < 1000_u64.pow(3) {
        format!("{:.2} MB", size as f64 / 1e6)
    } else if size < 1000_u64.pow(4) {
        format!("{:.2} GB", size as f64 / 1e9)
    } else {
        format!("{:.2} TB", size as f64 / 1e12)
    }
}

pub fn extension_of(path: &str) -> String {
    let name = path.rsplit('/').next().unwrap_or(path);
    match name.rfind('.') {
        Some(i) if i > 0 => name[i + 1..].to_string(),
        _ => String::new(),
    }
}

include!("mime_table.rs");

fn mime_for(relative_path: &str, is_dir: bool, mode: u32) -> String {
    if is_dir {
        return "inode/directory".to_string();
    }
    let ext = extension_of(relative_path);
    if !ext.is_empty() {
        if let Some(m) = MIME_TABLE.iter().find(|(e, _)| *e == ext) {
            return m.1.to_string();
        }
    }
    if mode & 0o100 != 0 {
        return "application/x-executable".to_string();
    }
    String::new()
}

fn ns_to_i128(secs: i64, nanos: u32) -> i128 {
    secs as i128 * 1_000_000_000 + nanos as i128
}

pub fn explore_node(parent: &str, name: &str, node_types: &NodeTypes) -> Node {
    let relative_path = name.to_string();
    let absolute_path = format!("{}/{}", parent.trim_end_matches('/'), name);
    let meta = std::fs::symlink_metadata(&absolute_path).ok();
    let mut node = Node {
        parent: parent.to_string(),
        relative_path: relative_path.clone(),
        absolute_path: absolute_path.clone(),
        extension: extension_of(&relative_path),
        is_dir: false,
        is_file: false,
        is_symlink: false,
        is_broken: false,
        is_readonly: false,
        mime_essence: String::new(),
        size: 0,
        human_size: "0 B".to_string(),
        permissions: Permissions::default(),
        created: 0,
        last_modified: 0,
        uid: 0,
        gid: 0,
        canonical: None,
        symlink: None,
    };
    if let Some(m) = meta {
        let mode = m.mode();
        let perms = Permissions::from_mode(mode);
        node.is_symlink = m.file_type().is_symlink();
        node.is_dir = m.file_type().is_dir();
        node.is_file = m.file_type().is_file();
        node.is_readonly = !perms.user_write;
        node.permissions = perms;
        node.size = m.size();
        node.human_size = human_size(node.size);
        node.uid = m.uid();
        node.gid = m.gid();
        node.created = ns_to_i128(m.ctime(), m.ctime_nsec() as u32);
        node.last_modified = ns_to_i128(m.mtime(), m.mtime_nsec() as u32);
        node.mime_essence = mime_for(&relative_path, node.is_dir, mode);
        if node.is_symlink {
            node.symlink = std::fs::read_link(&absolute_path)
                .ok()
                .map(|p| p.to_string_lossy().to_string());
            match std::fs::metadata(&absolute_path) {
                Ok(cm) => {
                    let cmode = cm.mode();
                    node.is_broken = false;
                    let cperms = Permissions::from_mode(cmode);
                    node.canonical = Some(ResolvedNode {
                        absolute_path: std::fs::canonicalize(&absolute_path)
                            .map(|p| p.to_string_lossy().to_string())
                            .unwrap_or_else(|_| absolute_path.clone()),
                        extension: extension_of(&relative_path),
                        is_dir: cm.file_type().is_dir(),
                        is_file: cm.file_type().is_file(),
                        is_readonly: !cperms.user_write,
                        mime_essence: mime_for(&relative_path, cm.file_type().is_dir(), cmode),
                        size: cm.size(),
                        human_size: human_size(cm.size()),
                        created: ns_to_i128(cm.ctime(), cm.ctime_nsec() as u32),
                        last_modified: ns_to_i128(cm.mtime(), cm.mtime_nsec() as u32),
                        uid: cm.uid(),
                        gid: cm.gid(),
                    });
                }
                Err(_) => {
                    node.is_broken = true;
                }
            }
        }
    } else {
        node.is_broken = true;
    }
    node
}

pub fn read_dir(parent: &str, node_types: &NodeTypes) -> Vec<Node> {
    let mut out = Vec::new();
    let rd = match std::fs::read_dir(parent) {
        Ok(r) => r,
        Err(_) => return out,
    };
    for e in rd.flatten() {
        let name = e.file_name().to_string_lossy().to_string();
        out.push(explore_node(parent, &name, node_types));
    }
    out
}
