pub fn apply_filters(nodes: Vec<Node>, filters: &[NodeFilterApplicable]) -> Vec<Node> {
    let mut out = nodes;
    for f in filters {
        out.retain(|n| is_match(&f.filter, &f.input, n));
    }
    out
}

/// Fuzzy matching with a score, mirroring a simple Smith-style algorithm.
fn fuzzy_score(pattern: &str, text: &str) -> Option<(i64, usize, usize)> {
    let pl: Vec<char> = pattern.to_lowercase().chars().collect();
    let tl: Vec<char> = text.to_lowercase().chars().collect();
    if pl.is_empty() {
        return Some((0, 0, tl.len()));
    }
    if pl.len() > tl.len() {
        return None;
    }
    // best (earliest) match
    let mut score: i64 = 0;
    let mut first_idx = None;
    let mut last_idx = 0usize;
    let mut ti = 0usize;
    for pc in &pl {
        let mut found = None;
        while ti < tl.len() {
            if tl[ti] == *pc {
                found = Some(ti);
                ti += 1;
                break;
            }
            ti += 1;
        }
        match found {
            Some(i) => {
                if first_idx.is_none() {
                    first_idx = Some(i);
                }
                last_idx = i;
                score += 1;
                if i > 0 && !tl[i - 1].is_alphanumeric() {
                    score += 5;
                }
            }
            None => return None,
        }
    }
    Some((score, first_idx.unwrap_or(0), last_idx))
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub struct SearchResult {
    pub index: usize,
    pub score: i64,
    pub begin: usize,
    pub end: usize,
}

pub fn search_nodes(nodes: &[Node], searcher: &Searcher) -> Option<Vec<usize>> {
    match searcher.algorithm {
        crate::config::SearchAlgorithm::Regex => {
            let mut out = Vec::new();
            for (i, n) in nodes.iter().enumerate() {
                if regex_match(&searcher.pattern, &n.relative_path) {
                    out.push(i);
                }
            }
            Some(out)
        }
        crate::config::SearchAlgorithm::Fuzzy => {
            let mut results: Vec<SearchResult> = Vec::new();
            for (i, n) in nodes.iter().enumerate() {
                if let Some((score, begin, end)) = fuzzy_score(&searcher.pattern, &n.relative_path) {
                    results.push(SearchResult {
                        index: i,
                        score,
                        begin,
                        end,
                    });
                }
            }
            if !searcher.unordered {
                let criteria = searcher.rank_criteria.clone().unwrap_or_else(|| vec![
                    RankCriterion::Score,
                    RankCriterion::Begin,
                    RankCriterion::End,
                    RankCriterion::Length,
                ]);
                results.sort_by(|a, b| {
                    for c in &criteria {
                        let cmp = match c {
                            RankCriterion::Score => b.score.cmp(&a.score),
                            RankCriterion::NegScore => a.score.cmp(&b.score),
                            RankCriterion::Begin => a.begin.cmp(&b.begin),
                            RankCriterion::NegBegin => b.begin.cmp(&a.begin),
                            RankCriterion::End => a.end.cmp(&b.end),
                            RankCriterion::NegEnd => b.end.cmp(&a.end),
                            RankCriterion::Length => (b.end - b.begin).cmp(&(a.end - a.begin)),
                            RankCriterion::NegLength => (a.end - a.begin).cmp(&(b.end - b.begin)),
                            RankCriterion::Index => a.index.cmp(&b.index),
                            RankCriterion::NegIndex => b.index.cmp(&a.index),
                        };
                        if cmp != std::cmp::Ordering::Equal {
                            return cmp;
                        }
                    }
                    std::cmp::Ordering::Equal
                });
            }
            Some(results.into_iter().map(|r| r.index).collect())
        }
    }
}

fn canonical_of(node: &Node) -> Option<&crate::node::ResolvedNode> {
    node.canonical.as_ref()
}

fn sort_key(sorter: &NodeSorter, node: &Node) -> SortKeyValue {
    use NodeSorter as S;
    match sorter {
        S::ByRelativePath => SortKeyValue::String(node.relative_path.clone()),
        S::ByIRelativePath => SortKeyValue::String(node.relative_path.to_lowercase()),
        S::ByExtension => SortKeyValue::String(node.extension.clone()),
        S::ByIsDir => SortKeyValue::Bool(node.is_dir),
        S::ByIsFile => SortKeyValue::Bool(node.is_file),
        S::ByIsSymlink => SortKeyValue::Bool(node.is_symlink),
        S::ByIsBroken => SortKeyValue::Bool(node.is_broken),
        S::ByIsReadonly => SortKeyValue::Bool(node.is_readonly),
        S::ByMimeEssence => SortKeyValue::String(node.mime_essence.clone()),
        S::BySize => SortKeyValue::U64(node.size),
        S::ByCreated => SortKeyValue::I128(node.created),
        S::ByLastModified => SortKeyValue::I128(node.last_modified),
        S::ByCanonicalAbsolutePath => SortKeyValue::String(
            canonical_of(node).map(|c| c.absolute_path.clone()).unwrap_or_default(),
        ),
        S::ByICanonicalAbsolutePath => SortKeyValue::String(
            canonical_of(node)
                .map(|c| c.absolute_path.to_lowercase())
                .unwrap_or_default(),
        ),
        S::ByCanonicalExtension => SortKeyValue::String(
            canonical_of(node).map(|c| c.extension.clone()).unwrap_or_default(),
        ),
        S::ByCanonicalIsDir => SortKeyValue::Bool(canonical_of(node).map(|c| c.is_dir).unwrap_or(false)),
        S::ByCanonicalIsFile => SortKeyValue::Bool(canonical_of(node).map(|c| c.is_file).unwrap_or(false)),
        S::ByCanonicalIsReadonly => SortKeyValue::Bool(
            canonical_of(node).map(|c| c.is_readonly).unwrap_or(false),
        ),
        S::ByCanonicalMimeEssence => SortKeyValue::String(
            canonical_of(node).map(|c| c.mime_essence.clone()).unwrap_or_default(),
        ),
        S::ByCanonicalSize => SortKeyValue::U64(canonical_of(node).map(|c| c.size).unwrap_or(0)),
        S::ByCanonicalCreated => SortKeyValue::I128(canonical_of(node).map(|c| c.created).unwrap_or(0)),
        S::ByCanonicalLastModified => SortKeyValue::I128(
            canonical_of(node).map(|c| c.last_modified).unwrap_or(0),
        ),
        S::BySymlinkAbsolutePath => {
            SortKeyValue::String(node.symlink.clone().unwrap_or_default())
        }
        S::ByISymlinkAbsolutePath => {
            SortKeyValue::String(node.symlink.clone().unwrap_or_default().to_lowercase())
        }
        S::BySymlinkExtension => {
            SortKeyValue::String(crate::node::extension_of(&node.symlink.clone().unwrap_or_default()))
        }
        S::BySymlinkIsDir => {
            SortKeyValue::Bool(node.symlink.as_ref().map(|p| std::fs::metadata(p).map(|m| m.is_dir()).unwrap_or(false)).unwrap_or(false))
        }
        S::BySymlinkIsFile => {
            SortKeyValue::Bool(node.symlink.as_ref().map(|p| std::fs::metadata(p).map(|m| m.is_file()).unwrap_or(false)).unwrap_or(false))
        }
        S::BySymlinkIsReadonly => SortKeyValue::Bool(false),
        S::BySymlinkMimeEssence => {
            SortKeyValue::String(node.symlink.as_ref().map(|p| {
                let ext = crate::node::extension_of(p);
                crate::node::MIME_TABLE
                    .iter()
                    .find(|(e, _)| *e == ext)
                    .map(|(_, m)| m.to_string())
                    .unwrap_or_default()
            }).unwrap_or_default())
        }
        S::BySymlinkSize => {
            SortKeyValue::U64(node.symlink.as_ref().map(|p| std::fs::metadata(p).map(|m| m.len()).unwrap_or(0)).unwrap_or(0))
        }
        S::BySymlinkCreated => SortKeyValue::I128(0),
        S::BySymlinkLastModified => SortKeyValue::I128(0),
    }
}

enum SortKeyValue {
    String(String),
    Bool(bool),
    U64(u64),
    I128(i128),
}

impl SortKeyValue {
    fn cmp(&self, other: &SortKeyValue) -> std::cmp::Ordering {
        match (self, other) {
            (SortKeyValue::String(a), SortKeyValue::String(b)) => a.cmp(b),
            (SortKeyValue::Bool(a), SortKeyValue::Bool(b)) => a.cmp(b),
            (SortKeyValue::U64(a), SortKeyValue::U64(b)) => a.cmp(b),
            (SortKeyValue::I128(a), SortKeyValue::I128(b)) => a.cmp(b),
            _ => std::cmp::Ordering::Equal,
        }
    }
}

pub fn apply_sorters(mut nodes: Vec<Node>, sorters: &[NodeSorterApplicable]) -> Vec<Node> {
    if sorters.is_empty() {
        return nodes;
    }
    let keys: Vec<Vec<SortKeyValue>> = nodes
        .iter()
        .map(|n| sorters.iter().map(|s| sort_key(&s.sorter, n)).collect())
        .collect();
    let mut order: Vec<usize> = (0..nodes.len()).collect();
    order.sort_by(|a, b| {
        for (i, s) in sorters.iter().enumerate() {
            let cmp = keys[*a][i].cmp(&keys[*b][i]);
            let cmp = if s.reverse { cmp.reverse() } else { cmp };
            if cmp != std::cmp::Ordering::Equal {
                return cmp;
            }
        }
        a.cmp(b)
    });
    nodes = order.into_iter().map(|i| nodes.swap_remove(i)).collect();
    nodes
}

pub fn explore(
    parent: &str,
    node_types: &crate::config::NodeTypes,
    filters: &[NodeFilterApplicable],
    sorters: &[NodeSorterApplicable],
    searcher: Option<&Searcher>,
) -> (Vec<Node>, Option<Vec<usize>>) {
    let nodes = crate::node::read_dir(parent, node_types);
    let nodes = apply_filters(nodes, filters);
    let nodes = apply_sorters(nodes, sorters);
    let search_order = searcher.and_then(|s| search_nodes(&nodes, s));
    (nodes, search_order)
}
