/// Fuzzy matching with a score, mirroring a simple Smith-style algorithm.
fn fuzzy_score(pattern: &str, text: &str) -> Option<(i64, usize, usize)> {
    let pl: Vec<char> = pattern.to_lowercase().chars().collect();
    let tl: Vec<char> = text.to_lowercase().chars().collect();
    if pl.is_empty() {
        return Some((0, 0, tl.len()));
    }
    if pl.len() > tl.len() {
        return None;
    }
    // best (earliest) match
    let mut score: i64 = 0;
    let mut first_idx = None;
    let mut last_idx = 0usize;
    let mut ti = 0usize;
    for pc in &pl {
        let mut found = None;
        while ti < tl.len() {
            if tl[ti] == *pc {
                found = Some(ti);
                ti += 1;
                break;
            }
            ti += 1;
        }
        match found {
            Some(i) => {
                if first_idx.is_none() {
                    first_idx = Some(i);
                }
                last_idx = i;
                score += 1;
                if i > 0 && !tl[i - 1].is_alphanumeric() {
                    score += 5;
                }
            }
            None => return None,
        }
    }
    Some((score, first_idx.unwrap_or(0), last_idx))
}

