                    out.push(i);
                }
            }
            Some(out)
        }
        crate::config::SearchAlgorithm::Fuzzy => {
            let mut results: Vec<SearchResult> = Vec::new();
            for (i, n) in nodes.iter().enumerate() {
                if let Some((score, begin, end)) = fuzzy_score(&searcher.pattern, &n.relative_path) {
                    results.push(SearchResult {
                        index: i,
                        score,
                        begin,
                        end,
                    });
                }
            }
            if !searcher.unordered {
                let criteria = searcher.rank_criteria.clone().unwrap_or_else(|| vec![
                    RankCriterion::Score,
                    RankCriterion::Begin,
                    RankCriterion::End,
                    RankCriterion::Length,
                ]);
                results.sort_by(|a, b| {
                    for c in &criteria {
                        let cmp = match c {
                            RankCriterion::Score => b.score.cmp(&a.score),
                            RankCriterion::NegScore => a.score.cmp(&b.score),
                            RankCriterion::Begin => a.begin.cmp(&b.begin),
                            RankCriterion::NegBegin => b.begin.cmp(&a.begin),
                            RankCriterion::End => a.end.cmp(&b.end),
                            RankCriterion::NegEnd => b.end.cmp(&a.end),
                            RankCriterion::Length => (b.end - b.begin).cmp(&(a.end - a.begin)),
                            RankCriterion::NegLength => (a.end - a.begin).cmp(&(b.end - b.begin)),
                            RankCriterion::Index => a.index.cmp(&b.index),
                            RankCriterion::NegIndex => b.index.cmp(&a.index),
                        };
                        if cmp != std::cmp::Ordering::Equal {
                            return cmp;
                        }
                    }
                    std::cmp::Ordering::Equal
                });
            }
            Some(results.into_iter().map(|r| r.index).collect())
        }
    }
}

