enum SortKeyValue {
    String(String),
    Bool(bool),
    U64(u64),
    I128(i128),
}

impl SortKeyValue {
    fn cmp(&self, other: &SortKeyValue) -> std::cmp::Ordering {
        match (self, other) {
            (SortKeyValue::String(a), SortKeyValue::String(b)) => a.cmp(b),
            (SortKeyValue::Bool(a), SortKeyValue::Bool(b)) => a.cmp(b),
            (SortKeyValue::U64(a), SortKeyValue::U64(b)) => a.cmp(b),
            (SortKeyValue::I128(a), SortKeyValue::I128(b)) => a.cmp(b),
            _ => std::cmp::Ordering::Equal,
        }
    }
}

pub fn apply_sorters(mut nodes: Vec<Node>, sorters: &[NodeSorterApplicable]) -> Vec<Node> {
    if sorters.is_empty() {
        return nodes;
    }
    let keys: Vec<Vec<SortKeyValue>> = nodes
        .iter()
        .map(|n| sorters.iter().map(|s| sort_key(&s.sorter, n)).collect())
        .collect();
    let mut order: Vec<usize> = (0..nodes.len()).collect();
    order.sort_by(|a, b| {
        for (i, s) in sorters.iter().enumerate() {
            let cmp = keys[*a][i].cmp(&keys[*b][i]);
            let cmp = if s.reverse { cmp.reverse() } else { cmp };
            if cmp != std::cmp::Ordering::Equal {
                return cmp;
            }
        }
        a.cmp(b)
    });
    nodes = order.into_iter().map(|i| nodes.swap_remove(i)).collect();
    nodes
}

pub fn explore(
    parent: &str,
    node_types: &crate::config::NodeTypes,
    filters: &[NodeFilterApplicable],
    sorters: &[NodeSorterApplicable],
    searcher: Option<&Searcher>,
) -> (Vec<Node>, Option<Vec<usize>>) {
    let nodes = crate::node::read_dir(parent, node_types);
    let nodes = apply_filters(nodes, filters);
    let nodes = apply_sorters(nodes, sorters);
    let search_order = searcher.and_then(|s| search_nodes(&nodes, s));
    (nodes, search_order)
}
