//! Session directory and pipes.

use std::io::Write;

#[derive(Debug, Clone)]
pub struct Pipe {
    pub path: String,
    pub msg_in: String,
    pub selection_out: String,
    pub result_out: String,
    pub directory_nodes_out: String,
    pub global_help_menu_out: String,
    pub logs_out: String,
    pub history_out: String,
}

impl Pipe {
    pub fn from_session(session_path: &str) -> Pipe {
        let path = format!("{}/pipe", session_path);
        Pipe {
            msg_in: format!("{}/msg_in", path),
            selection_out: format!("{}/selection_out", path),
            result_out: format!("{}/result_out", path),
            directory_nodes_out: format!("{}/directory_nodes_out", path),
            global_help_menu_out: format!("{}/global_help_menu_out", path),
            logs_out: format!("{}/logs_out", path),
            history_out: format!("{}/history_out", path),
            path,
        }
    }

    pub fn all(&self) -> Vec<&str> {
        vec![
            &self.msg_in,
            &self.selection_out,
            &self.result_out,
            &self.directory_nodes_out,
            &self.global_help_menu_out,
            &self.logs_out,
            &self.history_out,
        ]
    }
}

pub fn session_path(pid: u32) -> String {
    format!(
        "{}/xplr/session/{}",
        std::env::temp_dir().to_string_lossy(),
        pid
    )
}

/// Writes the pipe files, separated by `sep` (which is also written at the end).
pub fn write_pipe(path: &str, entries: &[String], sep: u8) -> std::io::Result<()> {
    let mut buf: Vec<u8> = Vec::new();
    for e in entries {
        buf.extend_from_slice(e.as_bytes());
        buf.push(sep);
    }
    let mut f = std::fs::OpenOptions::new()
        .create(true)
        .write(true)
        .truncate(true)
        .open(path)?;
    f.write_all(&buf)
}

pub fn read_pipe(path: &str) -> Vec<String> {
    match std::fs::read(path) {
        Ok(c) => {
            let mut out = Vec::new();
            let mut cur: Vec<u8> = Vec::new();
            for b in c {
                if b == b'\0' || b == b'\n' {
                    out.push(String::from_utf8_lossy(&cur).to_string());
                    cur.clear();
                } else {
                    cur.push(b);
                }
            }
            if !cur.is_empty() {
                out.push(String::from_utf8_lossy(&cur).to_string());
            }
            out
        }
        Err(_) => Vec::new(),
    }
}

pub fn read_pipe_raw(path: &str) -> String {
    std::fs::read_to_string(path).unwrap_or_default()
}
