{"command": "cd /workspace && cat > src/app.rs <<'RSEOF'
//! The application state and message handling.

use crate::config::{Config, Layout, Mode};
use crate::explorer::{self, NodeFilterApplicable, NodeSorterApplicable, Searcher};
use crate::logs::{Log, LogLevel};
use crate::msg::Message;
use crate::node::Node;
use crate::session::Pipe;
use std::collections::BTreeMap;

pub const VERSION: &str = crate::cli::VERSION;

#[derive(Debug, Clone, PartialEq)]
pub struct DirectoryBuffer {
    pub parent: String,
    pub nodes: Vec<Node>,
}

#[derive(Debug, Clone, PartialEq)]
pub struct History {
    pub loc: usize,
    pub paths: Vec<String>,
}

#[derive(Debug, Clone, PartialEq)]
pub struct InputBuffer {
    pub buffer: Option<String>,
    pub prompt: String,
}

#[derive(Debug, Clone, PartialEq)]
pub struct ExplorerConfig {
    pub filters: Vec<NodeFilterApplicable>,
    pub sorters: Vec<NodeSorterApplicable>,
    pub searcher: Option<Searcher>,
}

pub struct App {
    pub config: Config,
    pub vroot: Option<String>,
    pub initial_vroot: Option<String>,
    pub pwd: String,
    pub initial_pwd: String,
    pub directory_buffer: Option<DirectoryBuffer>,
    pub directory_cache: BTreeMap<String, DirectoryBuffer>,
    pub selection: Vec<Node>,
    pub mode_stack: Vec<String>,
    pub layout_stack: Vec<String>,
    pub input: InputBuffer,
    pub logs: Vec<Log>,
    pub logs_hidden: bool,
    pub history: History,
    pub last_modes: Vec<String>,
    pub pipe: Pipe,
    pub session_path: String,
    pub pid: u32,
    pub explorer_config: ExplorerConfig,
    pub scroll_top: usize,
    pub hostname: String,
    pub fifo: Option<String>,
    pub enable_mouse: bool,
    pub read_only: bool,
    pub print_pwd_as_result: bool,
    pub write0: bool,
    pub quit_msg: Option<Message>,
    pub focus: usize,
    pub search_order: Option<Vec<usize>>,
    pub search_focused_index: Option<usize>,
    pub recover: bool,
}

impl App {
    pub fn new(config: Config, args: &crate::cli::Args) -> std::io::Result<App> {
        let pid = std::process::id();
        let session_path = crate::session::session_path(pid);
        std::fs::create_dir_all(&session_path)?;
        std::fs::create_dir_all(format!("{}/pipe", session_path))?;
        let pwd = std::env::current_dir()
            .map(|p| p.to_string_lossy().to_string())
            .unwrap_or_else(|_| "/".to_string());
        let hostname = hostname();
        let mut app = App {
            config,
            vroot: None,
            initial_vroot: None,
            pwd: pwd.clone(),
            initial_pwd: pwd.clone(),
            directory_buffer: None,
            directory_cache: BTreeMap::new(),
            selection: vec![],
            mode_stack: vec![],
            layout_stack: vec![],
            input: InputBuffer {
                buffer: None,
                prompt: "â".to_string(),
            },
            logs: vec![],
            logs_hidden: false,
            history: History { loc: 0, paths: vec![] },
            last_modes: vec![],
            pipe: Pipe::from_session(&session_path),
            session_path,
            pid,
            explorer_config: ExplorerConfig {
                filters: vec![],
                sorters: vec![],
                searcher: None,
            },
            scroll_top: 0,
            hostname,
            fifo: None,
            enable_mouse: false,
            read_only: false,
            print_pwd_as_result: false,
            write0: false,
            quit_msg: None,
            focus: 0,
            search_order: None,
            search_focused_index: None,
            recover: false,
        };
        app.input.prompt = app
            .config
            .general
            .prompt
            .format
            .clone()
            .unwrap_or_default();
        app.mode_stack
            .push(app.config.general.initial_mode.clone());
        app.layout_stack
            .push(app.config.general.initial_layout.clone());
        app.explorer_config.filters.push(NodeFilterApplicable {
            filter: crate::msg::NodeFilter::RelativePathDoesNotStartWith,
            input: ".".to_string(),
        });
        if let Some(s) = app.config.general.initial_sorting.clone() {
            app.explorer_config.sorters = s;
        }
        // initial path / selection from the command line
        if let Some(p) = &args.path {
            let abs = crate::path::absolutize(p);
            if std::fs::symlink_metadata(&abs)
                .map(|m| m.is_dir())
                .unwrap_or(false)
                && !args.force_focus
            {
                app.change_directory(&abs, false);
                app.focus = 0;
            } else {
                let parent = abs
                    .rsplit('/')
                    .nth(1)
                    .map(|s| s.to_string())
                    .unwrap_or_else(|| "/".to_string());
                let parent = if parent.is_empty() {
                    "/".to_string()
                } else {
                    parent
                };
                app.change_directory(&parent, false);
                if let Some(i) = app
                    .directory_buffer
                    .as_ref()
                    .and_then(|d| d.nodes.iter().position(|n| n.relative_path == abs.rsplit('/').next().unwrap_or("")))
                {
                    app.focus = i;
                }
            }
        }
        if !args.selection.is_empty() {
            let sel: Vec<String> = args.selection.iter().map(|s| crate::path::absolutize(s)).collect();
            app.select_paths(&sel);
        }
        if args.read_only {
            app.read_only = true;
        }
        if args.write0 {
            app.write0 = true;
        }
        if args.print_pwd_as_result {
            app.print_pwd_as_result = true;
        }
        if let Some(v) = &args.vroot {
            app.vroot = Some(crate::path::absolutize(v));
            app.initial_vroot = app.vroot.clone();
        }
        app.explore();
        Ok(app)
    }

    pub fn mode(&self) -> &Mode {
        let name = self.mode_stack.last().cloned().unwrap_or_default();
        self.config
            .modes
            .get(&name)
            .unwrap_or_else(|| self.config.modes.get("default").unwrap())
    }

    pub fn mode_name(&self) -> String {
        self.mode().name.clone()
    }

    pub fn layout(&self) -> Layout {
        let name = self.layout_stack.last().cloned().unwrap_or_default();
        if let Some(l) = self.config.layouts.get(&name) {
            return l.clone();
        }
        self.config
            .layouts
            .get("default")
            .cloned()
            .unwrap_or(Layout::Nothing)
    }

    pub fn focused_node(&self) -> Option<&Node> {
        self.directory_buffer
            .as_ref()
            .and_then(|d| d.nodes.get(self.focus))
    }

