//! Handling of messages.

use crate::app::App;
use crate::explorer::{NodeFilterApplicable, NodeSorterApplicable, Searcher};
use crate::logs::LogLevel;
use crate::msg::Message;

pub enum Outcome {
    Continue,
    Quit(Vec<String>),
    Terminate,
}

pub fn handle(app: &mut App, message: Message) -> Outcome {
    match message {
        Message::ExplorePwd | Message::ExplorePwdAsync => {
            app.explore();
            Outcome::Continue
        }
        Message::ExploreParentsAsync => {
            app.explore();
            Outcome::Continue
        }
        Message::TryCompletePath => {
            try_complete_path(app);
            Outcome::Continue
        }
        Message::ClearScreen => Outcome::Continue,
        Message::Refresh => {
            app.refresh();
            Outcome::Continue
        }
        Message::FocusNext => {
            focus_next(app, 1);
            Outcome::Continue
        }
        Message::FocusNextSelection => {
            focus_next_selection(app, 1);
            Outcome::Continue
        }
        Message::FocusNextByRelativeIndex(n) => {
            focus_next(app, n as usize);
            Outcome::Continue
        }
        Message::FocusNextByRelativeIndexFromInput => {
            let n = app
                .input
                .buffer
                .clone()
                .and_then(|b| b.parse::<usize>().ok())
                .unwrap_or(1);
            focus_next(app, n);
            Outcome::Continue
        }
        Message::FocusPrevious => {
            focus_previous(app, 1);
            Outcome::Continue
        }
        Message::FocusPreviousSelection => {
            focus_previous_selection(app, 1);
            Outcome::Continue
        }
        Message::FocusPreviousByRelativeIndex(n) => {
            focus_previous(app, n as usize);
            Outcome::Continue
        }
        Message::FocusPreviousByRelativeIndexFromInput => {
            let n = app
                .input
                .buffer
                .clone()
                .and_then(|b| b.parse::<usize>().ok())
                .unwrap_or(1);
            focus_previous(app, n);
            Outcome::Continue
        }
        Message::FocusFirst => {
            app.focus = 0;
            Outcome::Continue
        }
        Message::FocusLast => {
            let t = app.total();
            app.focus = t.saturating_sub(1);
            Outcome::Continue
        }
        Message::FocusPath(p) => {
            focus_path(app, &p);
            Outcome::Continue
        }
        Message::FocusPathFromInput => {
            let p = app.input.buffer.clone().unwrap_or_default();
            focus_path(app, &p);
            Outcome::Continue
        }
        Message::FocusByIndex(i) => {
            app.focus = i as usize;
            Outcome::Continue
        }
        Message::FocusByIndexFromInput => {
            if let Some(b) = app.input.buffer.clone() {
                if let Ok(i) = b.parse::<usize>() {
                    app.focus = i;
                }
            }
            Outcome::Continue
        }
        Message::FocusByFileName(name) => {
            if let Some(d) = &app.directory_buffer {
                if let Some(i) = d.nodes.iter().position(|n| n.relative_path == name) {
                    app.focus = i;
                }
            }
            Outcome::Continue
        }
        Message::ScrollUp => {
            scroll_up(app, 1);
            Outcome::Continue
        }
        Message::ScrollDown => {
            scroll_down(app, 1);
            Outcome::Continue
        }
        Message::ScrollUpHalf => {
            scroll_up(app, app.table_height() as usize / 2);
            Outcome::Continue
        }
        Message::ScrollDownHalf => {
            scroll_down(app, app.table_height() as usize / 2);
            Outcome::Continue
        }
        Message::ChangeDirectory(p) => {
            change_directory(app, &p);
            Outcome::Continue
        }
        Message::Enter => {
            if let Some(n) = app.focused_node().cloned() {
                if n.is_dir {
                    change_directory(app, &n.absolute_path);
                }
            }
            Outcome::Continue
        }
        Message::Back => {
            let parent = parent_of(&app.pwd);
            change_directory(app, &parent);
            Outcome::Continue
        }
        Message::LastVisitedPath => {
            let h = &app.history;
            if h.loc > 0 {
                let loc = h.loc - 1;
                let p = h.paths[loc].clone();
                go_history(app, loc, &p);
            }
            Outcome::Continue
        }
        Message::NextVisitedPath => {
            let h = &app.history;
            if h.loc + 1 < h.paths.len() {
                let loc = h.loc + 1;
                let p = h.paths[loc].clone();
                go_history(app, loc, &p);
            }
            Outcome::Continue
        }
        Message::PreviousVisitedDeepBranch => Outcome::Continue,
        Message::NextVisitedDeepBranch => Outcome::Continue,
        Message::FollowSymlink => {
            if let Some(n) = app.focused_node().cloned() {
                if let Some(c) = &n.canonical {
                    if c.is_dir {
                        change_directory(app, &c.absolute_path);
                    } else {
                        focus_path(app, &c.absolute_path);
                    }
                }
            }
            Outcome::Continue
        }
