                .visible_nodes()
                .into_iter()
                .map(|n| n.absolute_path.clone())
                .collect();
            let all_selected = paths
                .iter()
                .all(|p| app.selection.iter().any(|s| &s.absolute_path == p));
            if all_selected {
                for p in paths {
                    remove_selection(app, &p);
