        Message::ToggleNodeFilter(f) => {
            let fa = NodeFilterApplicable {
                filter: f.filter,
                input: f.input,
            };
            if app.explorer_config.filters.iter().any(|x| *x == fa) {
                app.explorer_config.filters.retain(|x| *x != fa);
            } else {
                app.explorer_config.filters.push(fa);
