            } else {
                app.explorer_config.sorters.push(NodeSorterApplicable {
                    sorter: s.sorter,
                    reverse: s.reverse,
                });
            }
            app.explore();
            Outcome::Continue
        }
        Message::ReverseNodeSorters => {
            for x in app.explorer_config.sorters.iter_mut() {
                x.reverse = !x.reverse;
            }
            app.explore();
            Outcome::Continue
        }
        Message::RemoveLastNodeSorter => {
