            search_with(app, &p, crate::config::SearchAlgorithm::Fuzzy, true);
            Outcome::Continue
        }
        Message::SearchRegex(p) => {
            search_with(app, &p, crate::config::SearchAlgorithm::Regex, false);
            Outcome::Continue
        }
        Message::SearchRegexFromInput => {
            let p = app.input.buffer.clone().unwrap_or_default();
            search_with(app, &p, crate::config::SearchAlgorithm::Regex, false);
            Outcome::Continue
        }
        Message::SearchRegexUnordered(p) => {
