        Message::ResetVroot => {
            app.vroot = app.initial_vroot.clone();
            Outcome::Continue
        }
        Message::SetInputPrompt(p) => {
            app.input.prompt = p;
            Outcome::Continue
        }
        Message::UpdateInputBuffer(op) => {
