                let cut = t.rfind(' ').map(|i| i + 1).unwrap_or(0);
                app.input.buffer = Some(b[..cut].to_string());
            }
            Outcome::Continue
        }
        Message::ResetInputBuffer => {
            app.input.buffer = Some(String::new());
            Outcome::Continue
        }
        Message::SwitchMode(m) => {
            switch_mode(app, &m, false);
            Outcome::Continue
        }
        Message::SwitchModeKeepingInputBuffer(m) => {
            switch_mode(app, &m, true);
            Outcome::Continue
        }
        Message::SwitchModeBuiltin(m) => {
            switch_mode(app, &m, false);
            Outcome::Continue
        }
        Message::SwitchModeBuiltinKeepingInputBuffer(m) => {
            switch_mode(app, &m, true);
