        Message::PopMode => {
            pop_mode(app, false);
            Outcome::Continue
        }
        Message::PopModeKeepingInputBuffer => {
            pop_mode(app, true);
            Outcome::Continue
        }
        Message::SwitchLayout(l) => {
            switch_layout(app, &l);
            Outcome::Continue
        }
        Message::SwitchLayoutBuiltin(l) => {
            switch_layout(app, &l);
            Outcome::Continue
        }
        Message::SwitchLayoutCustom(l) => {
            switch_layout(app, &l);
            Outcome::Continue
        }
        Message::Call(c) => {
            crate::pipes::call(app, &c, false, false);
            Outcome::Continue
        }
        Message::Call0(c) => {
            crate::pipes::call(app, &c, false, true);
            Outcome::Continue
        }
        Message::CallSilently(c) => {
            crate::pipes::call(app, &c, true, false);
            Outcome::Continue
        }
        Message::CallSilently0(c) => {
            crate::pipes::call(app, &c, true, true);
            Outcome::Continue
        }
        Message::BashExec(s) => {
            let c = crate::msg::Command { command: s, args: None };
            crate::pipes::call(app, &c, false, false);
            Outcome::Continue
        }
        Message::BashExec0(s) => {
            let c = crate::msg::Command { command: s, args: None };
            crate::pipes::call(app, &c, false, true);
            Outcome::Continue
        }
        Message::BashExecSilently(s) => {
            let c = crate::msg::Command { command: s, args: None };
            crate::pipes::call(app, &c, true, false);
            Outcome::Continue
        }
        Message::BashExecSilently0(s) => {
            let c = crate::msg::Command { command: s, args: None };
            crate::pipes::call(app, &c, true, true);
            Outcome::Continue
        }
        Message::CallLua(_) | Message::CallLuaSilently(_) => Outcome::Continue,
        Message::LuaEval(_) | Message::LuaEvalSilently(_) => Outcome::Continue,
        Message::Select => {
            if let Some(n) = app.focused_node().cloned() {
                add_selection(app, n);
            }
            Outcome::Continue
