            Outcome::Continue
        }
        Message::Debug(m) => {
            app.log(LogLevel::Info, &m);
            Outcome::Continue
        }
        Message::Quit => Outcome::Quit(vec![]),
        Message::PrintPwdAndQuit => Outcome::Quit(vec![format!("{}\n", app.pwd)]),
        Message::PrintFocusPathAndQuit => {
            let out = app
                .focused_node()
                .map(|n| n.absolute_path.clone())
                .unwrap_or_else(|| app.pwd.clone());
            Outcome::Quit(vec![format!("{}\n", out)])
        }
        Message::PrintSelectionAndQuit => {
            let sep = if app.write0 { "\0" } else { "\n" };
            let out = app
                .selection
                .iter()
                .map(|n| n.absolute_path.clone())
                .collect::<Vec<_>>()
                .join(sep);
            Outcome::Quit(vec![out])
        }
        Message::PrintResultAndQuit => {
            let sep = if app.write0 { "\0" } else { "\n" };
            let out = if app.print_pwd_as_result {
                app.pwd.clone()
            } else {
                app.result().join(sep)
            };
            Outcome::Quit(vec![out])
        }
        Message::PrintAppStateAndQuit => {
            let yaml = crate::yamlout::app_state_yaml(app);
            Outcome::Quit(vec![yaml])
        }
        Message::Terminate => Outcome::Terminate,
    }
}

fn parent_of(p: &str) -> String {
    let t = p.trim_end_matches('/');
    match t.rfind('/') {
        Some(0) => "/".to_string(),
        Some(i) => t[..i].to_string(),
        None => "/".to_string(),
    }
}

pub fn focus_next(app: &mut App, n: usize) {
    let total = app.total();
    if total == 0 {
        return;
    }
    if app.config.general.enforce_bounded_index_navigation {
        app.focus = (app.focus + n).min(total - 1);
    } else {
        app.focus = (app.focus + n) % total;
    }
}

pub fn focus_previous(app: &mut App, n: usize) {
    let total = app.total();
    if total == 0 {
        return;
    }
    if app.config.general.enforce_bounded_index_navigation {
        app.focus = app.focus.saturating_sub(n);
    } else {
        app.focus = (app.focus + total - n % total) % total;
    }
}

fn focus_next_selection(app: &mut App, _n: usize) {
    let sel: Vec<String> = app.selection.iter().map(|s| s.absolute_path.clone()).collect();
    if sel.is_empty() {
        return;
    }
    let nodes = app.visible_nodes();
    let cur = nodes.get(app.focus).map(|n| n.absolute_path.clone());
    // find the next selected node after the focus
    let mut best: Option<usize> = None;
    for (i, n) in nodes.iter().enumerate() {
        if sel.contains(&n.absolute_path) {
            match &cur {
                Some(c) if n.absolute_path == *c => continue,
                Some(c) if i <= app.focus => continue,
                _ => {}
            }
            if best.is_none() {
                best = Some(i);
            }
        }
    }
    if let Some(i) = best {
        app.focus = i;
    }
}

fn focus_previous_selection(app: &mut App, _n: usize) {
    let sel: Vec<String> = app.selection.iter().map(|s| s.absolute_path.clone()).collect();
    if sel.is_empty() {
        return;
    }
    let nodes = app.visible_nodes();
    let mut best: Option<usize> = None;
    for (i, n) in nodes.iter().enumerate().rev() {
        if sel.contains(&n.absolute_path) && i < app.focus {
            best = Some(i);
        }
    }
    if let Some(i) = best {
        app.focus = i;
    }
}

pub fn focus_path(app: &mut App, p: &str) {
    let abs = crate::path::absolutize(p);
    if let Some(d) = &app.directory_buffer {
        if let Some(i) = d.nodes.iter().position(|n| n.absolute_path == abs) {
            app.focus = i;
            return;
        }
        if let Some(i) = d.nodes.iter().position(|n| n.relative_path == p) {
            app.focus = i;
            return;
        }
    }
    let _ = abs;
}

fn select_path(app: &mut App, p: &str) {
    let abs = crate::path::absolutize(p);
    let node = app
        .directory_buffer
        .as_ref()
        .and_then(|d| d.nodes.iter().find(|n| n.absolute_path == abs))
        .cloned();
    if let Some(n) = node {
        add_selection(app, n);
    }
}

pub fn add_selection(app: &mut App, n: crate::node::Node) {
    if !app.selection.iter().any(|s| s.absolute_path == n.absolute_path) {
        app.selection.push(n);
    }
}

pub fn remove_selection(app: &mut App, path: &str) {
    app.selection.retain(|s| s.absolute_path != path);
}

pub fn change_directory(app: &mut App, path: &str) {
    let path = crate::path::absolutize(path);
    if crate::path::exists(&path) {
        app.change_directory(&path, true);
        app.focus = 0;
        app.scroll_top = 0;
        app.explore();
    } else {
        app.log(LogLevel::Error, &format!("could not change directory to {}", path));
    }
}

fn go_history(app: &mut App, loc: usize, path: &str) {
    let target = crate::path::absolutize(path);
    if crate::path::exists(&target) && std::fs::symlink_metadata(&target).map(|m| m.is_dir()).unwrap_or(false) {
        app.change_directory(&target, false);
        app.focus = 0;
        app.scroll_top = 0;
        app.explore();
    }
    app.history.loc = loc;
}

fn switch_mode(app: &mut App, name: &str, keep_input: bool) {
    let current = app.mode_stack.last().cloned();
    if let Some(c) = current {
        if !app.last_modes.contains(&c) {
            app.last_modes.push(c);
        }
    }
    app.mode_stack.push(name.to_string());
    if !keep_input {
        app.input.buffer = None;
    }
    app.input.prompt = app
        .mode()
        .prompt
        .clone()
        .or_else(|| app.config.general.prompt.format.clone())
        .unwrap_or_default();
}

fn pop_mode(app: &mut App, keep_input: bool) {
    app.mode_stack.pop();
    if !keep_input {
        app.input.buffer = None;
    }
    app.input.prompt = app
        .mode()
        .prompt
        .clone()
        .or_else(|| app.config.general.prompt.format.clone())
        .unwrap_or_default();
}

fn switch_layout(app: &mut App, name: &str) {
    if app.config.layouts.contains_key(name) {
        app.layout_stack.push(name.to_string());
    }
}

fn scroll_up(app: &mut App, n: usize) {
    app.scroll_top = app.scroll_top.saturating_sub(n);
}

fn scroll_down(app: &mut App, n: usize) {
    let total = app.total();
    let height = app.table_height() as usize;
    if height == 0 {
        return;
    }
    let max_top = total.saturating_sub(height);
    app.scroll_top = (app.scroll_top + n).min(max_top);
}

fn search(app: &mut App, pattern: &str, unordered: bool) {
    let alg = app.config.general.search.algorithm;
    search_with(app, pattern, alg, unordered);
}

fn search_with(
    app: &mut App,
    pattern: &str,
    alg: crate::config::SearchAlgorithm,
    unordered: bool,
) {
    let nodes = app.directory_buffer.as_ref().map(|d| d.nodes.clone()).unwrap_or_default();
    let searcher = Searcher {
        pattern: pattern.to_string(),
        recoverable_focus: None,
        algorithm: alg,
        unordered: unordered || app.config.general.search.unordered,
        exact_mode: app.config.general.search.exact_mode,
        rank_criteria: app.config.general.search.rank_criteria.clone().map(|_| vec![]),
    };
    let order = crate::explorer::search_nodes(&nodes, &searcher);
    app.explorer_config.searcher = Some(searcher);
    app.search_order = order;
    app.focus = 0;
}

fn try_complete_path(app: &mut App) {
    let buf = app.input.buffer.clone().unwrap_or_default();
    if buf.is_empty() {
        return;
    }
    let abs = if buf.starts_with('/') {
        buf.clone()
    } else {
        format!("{}/{}", app.pwd.trim_end_matches('/'), buf)
    };
    let dir = match abs.rfind('/') {
        Some(i) if i == 0 => "/".to_string(),
        Some(i) => abs[..i].to_string(),
        None => app.pwd.clone(),
    };
    let stem = abs.rsplit('/').next().unwrap_or("").to_string();
    let entries = crate::node::read_dir(&dir, &app.config.node_types);
    let matches: Vec<String> = entries
        .iter()
        .filter(|n| n.relative_path.starts_with(&stem))
        .map(|n| n.relative_path.clone())
        .collect();
    if matches.len() == 1 {
        let full = format!("{}/{}", dir.trim_end_matches('/'), matches[0]);
        app.input.buffer = Some(full);
    } else if !matches.is_empty() {
        // common prefix
        let mut prefix = matches[0].clone();
        for m in &matches {
            while !m.starts_with(&prefix) {
                prefix.pop();
            }
        }
        if prefix.len() > stem.len() {
            app.input.buffer = Some(format!(
                "{}/{}",
                dir.trim_end_matches('/'),
                prefix
            ));
        }
    }
}
