//! Input buffer operations.

use crate::msg::InputOperation;

pub fn apply(buffer: &mut Option<String>, op: &InputOperation) {
    let b = buffer.clone().unwrap_or_default();
    let mut chars: Vec<char> = b.chars().collect();
    match op {
        InputOperation::SetCursor(_) => {}
        InputOperation::InsertCharacter(c) => chars.push(c.chars().next().unwrap_or(' ')),
        InputOperation::GoToPreviousCharacter => {}
        InputOperation::GoToNextCharacter => {}
        InputOperation::GoToPreviousWord => {}
        InputOperation::GoToNextWord => {}
        InputOperation::GoToStart => {}
        InputOperation::GoToEnd => {}
        InputOperation::DeletePreviousCharacter => {
            chars.pop();
        }
        InputOperation::DeleteNextCharacter => {}
        InputOperation::DeletePreviousWord => {}
        InputOperation::DeleteNextWord => {}
        InputOperation::DeleteLine => chars.clear(),
        InputOperation::DeleteTillEnd => {}
    }
    *buffer = Some(chars.into_iter().collect());
}
