        }
        Message::AddNodeSorter(s) => {
            app.explorer_config.sorters.push(NodeSorterApplicable {
                sorter: s.sorter,
                reverse: s.reverse,
            });
            app.explore();
            Outcome::Continue
        }
        Message::RemoveNodeSorter(s) => {
            app.explorer_config.sorters.retain(|x| x.sorter != s);
            app.explore();
            Outcome::Continue
        }
        Message::ReverseNodeSorter(s) => {
            for x in app.explorer_config.sorters.iter_mut() {
                if x.sorter == s {
                    x.reverse = !x.reverse;
                }
            }
            app.explore();
            Outcome::Continue
        }
        Message::ToggleNodeSorter(s) => {
            if let Some(x) = app
                .explorer_config
                .sorters
                .iter_mut()
                .find(|x| x.sorter == s.sorter)
            {
                x.reverse = !x.reverse;
            } else {
                app.explorer_config.sorters.push(NodeSorterApplicable {
                    sorter: s.sorter,
                    reverse: s.reverse,
                });
            }
            app.explore();
            Outcome::Continue
        }
        Message::ReverseNodeSorters => {
            for x in app.explorer_config.sorters.iter_mut() {
                x.reverse = !x.reverse;
            }
            app.explore();
            Outcome::Continue
        }
        Message::RemoveLastNodeSorter => {
            app.explorer_config.sorters.pop();
            app.explore();
            Outcome::Continue
        }
        Message::ResetNodeSorters => {
            app.explorer_config.sorters = app
                .config
                .general
                .initial_sorting
