//! Running external commands with the pipes.

use crate::app::App;
use crate::logs::LogLevel;
use crate::msg::Command;

pub fn call(app: &mut App, command: &Command, silently: bool, null_separated: bool) {
    let _ = silently;
    // create the pipe files
    let sep: u8 = if null_separated { b'\0' } else { b'\n' };
    let _ = crate::session::write_pipe(&app.pipe.selection_out, &selection_paths(app), sep);
    let _ = crate::session::write_pipe(&app.pipe.result_out, &result_paths(app), sep);
    let _ = crate::session::write_pipe(
        &app.pipe.directory_nodes_out,
        &node_paths(app),
        sep,
    );
    let _ = crate::session::write_pipe(&app.pipe.logs_out, &log_lines(app), sep);
    let _ = crate::session::write_pipe(&app.pipe.history_out, &history_paths(app), sep);
    let _ = crate::session::write_pipe(&app.pipe.global_help_menu_out, &help_menu(app), sep);
    let _ = crate::session::write_pipe(&app.pipe.msg_in, &[], sep);
    let env = crate::env::app_env(app);
    let mut cmd = std::process::Command::new(&command.command);
    if let Some(args) = &command.args {
        cmd.args(args);
    }
    for (k, v) in &env {
        cmd.env(k, v);
    }
    match cmd.spawn() {
        Ok(mut child) => {
            let _ = child.wait();
        }
        Err(e) => {
            if !silently {
                app.log(LogLevel::Error, &e.to_string());
            }
        }
    }
    // read new messages from the pipe
    for m in crate::session::read_pipe(&app.pipe.msg_in) {
        if m.is_empty() {
            continue;
        }
        if let Ok(msg) = crate::cli::parse_message_arg(&m) {
            let _ = crate::handler::handle(app, msg);
        }
    }
    // clean up the pipes
    for p in app.pipe.all() {
        let _ = std::fs::remove_file(p);
    }
}

fn selection_paths(app: &App) -> Vec<String> {
    app.selection.iter().map(|n| n.absolute_path.clone()).collect()
}

fn result_paths(app: &App) -> Vec<String> {
    app.result()
}

fn node_paths(app: &App) -> Vec<String> {
    app.visible_nodes().iter().map(|n| n.absolute_path.clone()).collect()
}

fn log_lines(app: &App) -> Vec<String> {
    app.logs
        .iter()
        .map(|l| {
            format!(
                "{} {}    {}",
                l.at,
                level_name(l.level),
                l.message
            )
        })
        .collect()
}

pub fn level_name(l: LogLevel) -> &'static str {
    match l {
        LogLevel::Info => "INFO",
        LogLevel::Success => "SUCCESS",
        LogLevel::Warning => "WARNING",
        LogLevel::Error => "ERROR",
    }
}

fn history_paths(app: &App) -> Vec<String> {
    app.history.paths.clone()
}

pub fn help_menu(app: &App) -> Vec<String> {
    let mut out: Vec<String> = Vec::new();
    let mode_name = app.mode_name();
    let mut push_mode = |name: &str, mode: &crate::config::Mode| {
        out.push(format!("### {}", name));
        out.push(String::new());
        out.push(format!(
            " {:<16}| {:<26}| {}",
            "key", "remaps", "action"
        ));
        out.push(format!(
            " {:<16}| {:<26}| {}",
            "-".repeat(15),
            "-".repeat(25),
            "-".repeat(6)
        ));
        let mut keys: Vec<(&String, &crate::config::KeyBinding)> =
            mode.key_bindings.on_key.iter().collect();
        keys.sort_by(|a, b| a.0.cmp(b.0));
        for (k, kb) in keys {
            let remap = remap_for(app, k);
            out.push(format!(
                " {:<16}| {:<26}| {}",
                k,
                remap.unwrap_or_default(),
                kb.help.clone().unwrap_or_default()
            ));
        }
        for f in [
            "on_alphabet",
            "on_number",
            "on_alphanumeric",
            "on_special_character",
            "on_character",
            "on_navigation",
            "on_function",
        ] {
            if let Some(kb) = crate::config::key_binding_field(&mode.key_bindings, f) {
                let label = crate::config::field_label(f);
                if let Some(help) = &kb.help {
                    out.push(format!(" {:<16}| {:<26}| {}", label, "", help));
                }
            }
        }
        if let Some(kb) = &mode.key_bindings.default {
            if let Some(help) = &kb.help {
                out.push(format!(" {:<16}| {:<26}| {}", "[default]", "", help));
            }
        }
    };
    push_mode(&mode_name, app.mode());
    for (name, m) in app.config.modes.iter() {
        push_mode(name, m);
    }
    out
}

fn remap_for(app: &App, key: &str) -> Option<String> {
    for (name, m) in app.config.modes.iter() {
        for (k, kb) in m.key_bindings.on_key.iter() {
            if kb
                .messages
                .iter()
                .any(|msg| crate::msg::is_mode_switch_to(msg, name))
            {
                let _ = k;
            }
        }
    }
    None
}
