//! Minimal YAML emitter for the app state dump.

pub fn esc(s: &str) -> String {
    let mut out = String::from("'");
    for c in s.chars() {
        if c == '\'' {
            out.push_str("''");
        } else {
            out.push(c);
        }
    }
    out + "'"
}

pub fn scalar(v: Option<&str>) -> String {
    match v {
        None => "null".to_string(),
        Some(s) => {
            if s.is_empty() {
                "''".to_string()
            } else if s.contains('\n')
                || s.contains(':')
                || s.contains('#')
                || s.starts_with(' ')
                || s.ends_with(' ')
                || s.starts_with('\'')
            {
                esc(s)
            } else {
                s.to_string()
            }
        }
    }
}
