//! Terminal handling on top of crossterm + ratatui.

use ratatui::crossterm::event::{self, Event, KeyCode, KeyEvent, KeyModifiers};
use ratatui::crossterm::terminal as ct;
use std::io::Stdout;

pub struct Term {
    terminal: ratatui::Terminal<ratatui::backend::CrosstermBackend<Stdout>>,
}

impl Term {
    pub fn new() -> std::io::Result<Term> {
        let mut stdout = std::io::stdout();
        ct::enable_raw_mode()?;
        use std::io::Write;
        ct::EnterAlternateScreen.write_to(&mut std::io::stderr())?;
        stdout.flush()?;
        let backend = ratatui::backend::CrosstermBackend::new(stdout);
        let terminal = ratatui::Terminal::new(backend)?;
        Ok(Term { terminal })
    }

    pub fn draw<F: FnOnce(&mut ratatui::Frame)>(&mut self, f: F) -> std::io::Result<()> {
        self.terminal.draw(f)?;
        Ok(())
    }

    pub fn restore(&mut self) -> std::io::Result<()> {
        use std::io::Write;
        ct::LeaveAlternateScreen.write_to(&mut std::io::stderr())?;
        ct::disable_raw_mode()?;
        std::io::stderr().flush()?;
        Ok(())
    }
}

/// Maps a crossterm key event to the string xplr uses in its key bindings.
pub fn key_to_string(ev: &KeyEvent) -> String {
    let code = match ev.code {
        KeyCode::Backspace => "backspace".to_string(),
        KeyCode::Enter => "enter".to_string(),
        KeyCode::Left => "left".to_string(),
        KeyCode::Right => "right".to_string(),
        KeyCode::Up => "up".to_string(),
        KeyCode::Down => "down".to_string(),
        KeyCode::Home => "home".to_string(),
        KeyCode::End => "end".to_string(),
        KeyCode::PageUp => "page-up".to_string(),
        KeyCode::PageDown => "page-down".to_string(),
        KeyCode::Tab => "tab".to_string(),
        KeyCode::BackTab => "back-tab".to_string(),
        KeyCode::Delete => "delete".to_string(),
        KeyCode::Insert => "insert".to_string(),
        KeyCode::F(n) => format!("f{}", n),
        KeyCode::Char(c) => {
            if ev.modifiers.contains(KeyModifiers::CONTROL) {
                match c {
                    'c' => "ctrl-c".to_string(),
                    'i' => "ctrl-i".to_string(),
                    'm' => "enter".to_string(),
                    'h' => "backspace".to_string(),
                    '[' => "esc".to_string(),
                    _ => format!("ctrl-{}", c.to_lowercase()),
                }
            } else if ev.modifiers.contains(KeyModifiers::ALT) {
                format!("alt-{}", c.to_lowercase())
            } else {
                c.to_string()
            }
        }
        _ => return String::new(),
    };
    code
}

/// Polls for an event with a timeout, returning the key string if any.
pub fn read_key(timeout: std::time::Duration) -> Option<String> {
    match event::poll(timeout) {
        Ok(true) => match event::read() {
            Ok(Event::Key(ev)) => {
                if ev.kind == ratatui::crossterm::event::KeyEventKind::Release {
                    return None;
                }
                let s = key_to_string(&ev);
                if s.is_empty() {
                    None
                } else {
                    Some(s)
                }
            }
            _ => None,
        },
        _ => None,
    }
}
