//! The interactive main loop.

use crate::app::App;
use crate::cli::Args;
use crate::handler::{handle, Outcome};
use crate::term::Term;

pub fn run(args: Args) -> std::io::Result<()> {
    let config = crate::config::default_config();
    let mut app = match App::new(config, &args) {
        Ok(a) => a,
        Err(e) => {
            eprintln!("error: {}", e);
            std::process::exit(1);
        }
    };
    for m in &args.on_load {
        let _ = handle(&mut app, m.clone());
    }
    // The terminal may be unavailable; behave like xplr and report the error.
    let mut term = match Term::new() {
        Ok(t) => t,
        Err(e) => {
            eprintln!("error: {}", e);
            std::process::exit(1);
        }
    };
    let _ = draw(&mut app, &mut term);
    loop {
        let key = crate::term::read_key(std::time::Duration::from_millis(250));
        if let Some(k) = key {
            let msgs = crate::keys::lookup(&app, &k);
            for m in msgs {
                match handle(&mut app, m) {
                    Outcome::Continue => {}
                    Outcome::Quit(out) => {
                        let _ = term.restore();
                        for o in out {
                            print!("{}", o);
                        }
                        std::process::exit(0);
                    }
                    Outcome::Terminate => {
                        let _ = term.restore();
                        std::process::exit(0);
                    }
                }
            }
        }
        let _ = draw(&mut app, &mut term);
    }
}

fn draw(app: &mut App, term: &mut Term) -> std::io::Result<()> {
    term.draw(|f| crate::render::render(f, app))
}
