//! Looking up key bindings.

use crate::app::App;
use crate::config::{KeyBindings, Mode};
use crate::msg::Message;

pub fn lookup(app: &App, key: &str) -> Vec<Message> {
    let mode: &Mode = app.mode();
    let global: &KeyBindings = &app.config.general.global_key_bindings;
    // mode bindings take precedence
    if let Some(kb) = mode.key_bindings.on_key.get(key) {
        return kb.messages.clone();
    }
    for (field, matches) in [
        ("on_alphabet", key.chars().all(|c| c.is_ascii_lowercase())),
        ("on_number", key.chars().all(|c| c.is_ascii_digit())),
        (
            "on_alphanumeric",
            key.chars().all(|c| c.is_ascii_alphanumeric()),
        ),
    ] {
        if matches {
            if let Some(kb) = crate::config::key_binding_field(&mode.key_bindings, field) {
                return kb.messages.clone();
            }
        }
        let _ = field;
    }
    if let Some(kb) = &mode.key_bindings.default {
        if !kb.messages.is_empty() {
            return kb.messages.clone();
        }
    }
    if let Some(kb) = global.on_key.get(key) {
        return kb.messages.clone();
    }
    vec![]
}
